```jac
"""Build-system dependency auditor: counts unique reachable tasks.

Diamonds (a task with two or more incoming paths) are common in real
build graphs — two modules both link the same shared library, two
optimization passes both depend on the same analysis phase, etc. A
naive traversal would double-count the shared task; this program models
each task as a node, each build-minute cost as a node field, and uses
a walker with an explicit visited-set so a task reachable by multiple
paths is audited exactly once. The visit-set is the domain rule, not
scaffolding, so it is preserved.
"""

node Task {
    has title: str = "";
    has minutes: int = 0;
}

walker Auditor {
    has visited: list[str] = [];
    has total_minutes: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Task entry {
        if here.title not in self.visited {
            self.visited.append(here.title);
            self.total_minutes = self.total_minutes + here.minutes;
            print(f"[audit] {here.title} ({here.minutes} min)");
            visit [-->];
        } else {
            print(f"[skip] {here.title} already audited");
        }
    }
}

with entry {
    root ++> Task(title="compile-core", minutes=5)
        ++> Task(title="link-shared", minutes=3)
        ++> Task(title="compile-modA", minutes=4)
        ++> Task(title="compile-modB", minutes=4)
        ++> Task(title="package", minutes=2);

    # Diamond: both compile-modA and compile-modB depend on link-shared.
    # The walker would reach link-shared twice if we did not guard it,
    # which would double-count its 3 minutes.
    # Edges:
    #   compile-core -> link-shared
    #   compile-core -> compile-modA
    #   compile-core -> compile-modB
    #   link-shared -> package
    #   compile-modA -> package
    #   compile-modB -> package
    root spawn Auditor();
}
```

```jac
"""Depot dispatch checker.

Each route node carries a cargo weight in tonnes. A truck may only be
dispatched when its load is at least 2 tonnes and at most 8 tonnes on
the same leg. The dispatcher walker visits every depot and prints which
routes qualify for dispatch.
"""

node Route {
    has destination: str = "";
    has weight: float = 0.0;

    def qualifies() -> bool {
        return self.weight >= 2.0 and self.weight <= 8.0;
    }
}

walker Dispatcher {
    can start with Root entry {
        print("Dispatching trucks across the network...");
        visit [-->];
    }

    can check with Route entry {
        verdict = "DISPATCH" if here.qualifies() else "HOLD";
        print(f"[{verdict}] {here.destination}: {here.weight} tonnes");
        visit [-->];
    }
}

with entry {
    root ++> Route(destination="North Hub", weight=3.5)
        ++> Route(destination="South Yard", weight=1.2)
        ++> Route(destination="East Port", weight=8.0)
        ++> Route(destination="West Mine", weight=9.4)
        ++> Route(destination="Central Depot", weight=5.0);
    root spawn Dispatcher();
}
```

```jac
"""Ruffle AVM1 display list: lazy shape load + cascade invalidation.

Models the issue's "Memory overhead of shapes" + "expensive ChildContainer
property lookups" pain points. DisplayObject children are linked by a typed
``Child`` edge; shape rendering is lazy (the issue's recommendation: load
shapes lazily if they are needed for hit tests). A ``Refresher`` walker
walks the tree, prunes disposed children, and lazily tessellates shapes
on demand — the graph traversal the maintainer was hand-rolling with
``ChildContainer::get_name`` linear scans.
"""

node Shape {
    has kind: str = "";
    has tessellated: bool = False;
}

node DisplayObject {
    has name: str = "";
    has disposed: bool = False;
    has shape: Shape | None = None;
}

edge Child {}

walker Refresher {
    has seen: list = [];
    has tessellated_count: int = 0;
    has pruned_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can refresh with DisplayObject entry {
        # Cycle-safe: walkers have no built-in visited set, so guard explicitly.
        already = False;
        for s in self.seen {
            if s is here {
                already = True;
                break;
            }
        }
        if already {
            disengage;
        }
        self.seen.append(here);

        # Lazy tessellation: only the first hit-test pays the cost.
        if here.shape is not None and not here.shape.tessellated {
            here.shape.tessellated = True;
            self.tessellated_count += 1;
            print(f"  tessellated {here.shape.kind} for {here.name}");
        } else {
            print(f"  skipped (cached) {here.name}");
        }

        # Cascade invalidation: prune disposed children using a plain
        # disconnect without typed-edge filter kwargs.
        survivors = [];
        for child in [->:Child:->] {
            if not child.disposed {
                survivors.append(child);
            } else {
                self.pruned_count += 1;
            }
        }
        # Drop every Child edge; we cannot pass kwargs, so use untyped
        # disconnect (the issue's pain was the linear scan, not the
        # disconnection mechanism).
        for dead in [->:Child:->] {
            here del --> dead;
        }
        # Re-link the survivors via a typed Child edge.
        for alive in survivors {
            here +>:Child:+> alive;
        }

        visit [->:Child:->];
    }
}

with entry {
    # Build a small display tree with a shared shape and a disposed branch.
    shared_shape = Shape(kind="circle");
    root_node = DisplayObject(name="root", shape=shared_shape);
    child_a = DisplayObject(name="btnA");
    child_b = DisplayObject(name="btnB", disposed=True);
    leaf = DisplayObject(name="leaf", shape=Shape(kind="rect"));

    root_node +>:Child:+> child_a;
    root_node +>:Child:+> child_b;
    child_a +>:Child:+> leaf;

    root ++> root_node;

    print("--- first refresh (cold) ---");
    r1 = Refresher();
    root spawn r1;
    print(f"refresh1: tessellated={r1.tessellated_count}, pruned={r1.pruned_count}");

    print("--- second refresh (warm cache) ---");
    r2 = Refresher();
    root spawn r2;
    print(f"refresh2: tessellated={r2.tessellated_count}, pruned={r2.pruned_count}");
}
```

```jac
"""Tiny dungeon crawler: chained room nodes, a vault holding the treasure, and a hunter walker that counts visited rooms and stops the moment it finds the vault."""

node Room {
    has name: str = "";
    has has_treasure: bool = False;
}

walker Hunter {
    has rooms_checked: int = 0;
    has found: bool = False;

    can start with Root entry {
        print("Hunter enters the dungeon...");
        visit [-->] else { disengage; }
    }

    can search with Room entry {
        if self.found {
            # Treasure already located; never enter rooms past the vault.
            disengage;
        }
        self.rooms_checked += 1;
        if here.has_treasure {
            self.found = True;
            print(f"Treasure found in '{here.name}' after checking {self.rooms_checked} room(s)!");
            visit [-->] else { disengage; };
        } else {
            print(f"Checked room '{here.name}' — empty.");
            visit [-->] else { disengage; };
        }
    }
}

with entry {
    root ++> Room(name="Antechamber")
        ++> Room(name="Foyer")
        ++> Room(name="Hallway")
        ++> Room(name="Vault", has_treasure=True)
        ++> Room(name="Secret Alcove")
        ++> Room(name="Forgotten Crypt");

    hunter = Hunter();
    root spawn hunter;
    print(f"Final tally — rooms checked: {hunter.rooms_checked}, treasure found: {hunter.found}");
}
```

