```jac
"""Order auditor: skip invalid orders, halt the walk on fraud."""

node Order {
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print("Starting order audit");
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud {
            print(f"[HALT] fraud flagged order amount={here.amount}");
            disengage;
        } else {
            if not here.valid {
                print(f"[SKIP] invalid order amount={here.amount}");
            } else {
                print(f"[AUDIT] approved order amount={here.amount}");
            }
            visit [-->] else { disengage; };
        }
    }
}

with entry {
    root ++> Order(amount=120.0, valid=True, fraud=False)
        ++> Order(amount=45.0, valid=False, fraud=False)
        ++> Order(amount=200.0, valid=True, fraud=False)
        ++> Order(amount=999.0, valid=True, fraud=True)
        ++> Order(amount=15.0, valid=True, fraud=False);
    root spawn OrderAuditor();
}
```

```jac
"""Restaurant kitchen line health inspection.

A patrol walker visits every station (Grill, Fryer, ColdPrep) along the
kitchen line. At each station two checks run independently: a temperature
audit (flagging violations above 40 C) and a visit log. Both must fire at
every station regardless of the other's outcome.
"""

node Station {
    has name: str = "";
    has temperature: float = 0.0;

    def is_violation() -> bool {
        return self.temperature > 40.0;
    }
}

node Grill(Station) {}
node Fryer(Station) {}
node ColdPrep(Station) {}

walker Patrol {
    has violations: int = 0;
    has log: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can sweep with Station entry {
        self.log.append(here.name);
        if here.is_violation() {
            self.violations += 1;
            print(f"[VIOLATION] {here.name} at {here.temperature} C");
        } else {
            print(f"[OK] {here.name} at {here.temperature} C");
        }
        visit [-->];
    }
}

with entry {
    line = root ++> Grill(name="Grill", temperature=180.0)
        ++> Fryer(name="Fryer", temperature=165.0)
        ++> ColdPrep(name="ColdPrep", temperature=4.0);

    inspector = Patrol();
    root spawn inspector;

    print(f"Visited stations: {inspector.log}");
    print(f"Total violations: {inspector.violations}");
}
```

