```jac
"""Restaurant recommender: model eateries as nodes and filter by minimum rating with a finder walker."""

node Restaurant {
    has name: str = "";
    has cuisine: str = "";
    has rating: float = 0.0;
}

walker Finder {
    has min_rating: float = 0.0;
    has pass_label: str = "";

    def log_match(name: str, cuisine: str, rating: float) {
        if rating >= self.min_rating {
            print(f"  [{self.pass_label}] {name} — {cuisine} ({rating})");
        }
    }

    can start with Root entry {
        print(f"{self.pass_label}: restaurants rated {self.min_rating}+");
        visit [-->];
    }

    can inspect with Restaurant entry {
        self.log_match(here.name, here.cuisine, here.rating);
        visit [-->];
    }
}

with entry {
    root ++> Restaurant(name="Le Bernardin", cuisine="French", rating=4.8)
        ++> Restaurant(name="Shake Shack", cuisine="American", rating=4.2)
        ++> Restaurant(name="Trattoria Roma", cuisine="Italian", rating=4.5)
        ++> Restaurant(name="Corner Cafe", cuisine="American", rating=3.7)
        ++> Restaurant(name="Budget Bites", cuisine="Fast Food", rating=3.2);

    root spawn Finder(min_rating=4.5, pass_label="Date Night");
    root spawn Finder(min_rating=3.5, pass_label="Casual Lunch");
}
