```jac
"""Warehouse inventory audit.

Assigns a stable unique id to every item as a walker fans out across the
inventory graph, persists each visited item to storage during the walk, and
finally dumps the full graph hanging off the root for a visual sanity check.
"""

node Warehouse {
    has name: str = "";
}

node Item {
    has sku: str = "";
    has qty: int = 0;
    has stable_id: str = "";
    has persisted: bool = False;
}

edge Stocks {
    has aisle: str = "";
}

walker Auditor {
    has storage: dict[str, dict] = {};
    has counter: int = 0;

    can start with Root entry {
        print(f"Audit begin; storage empty={len(self.storage) == 0}");
        visit [-->];
    }

    can enter with Warehouse entry {
        print(f"  entering warehouse {here.name}");
        visit [-->];
    }

    can inspect with Item entry {
        self.counter += 1;
        sid = f"ITEM-{self.counter:04d}";
        here.stable_id = sid;
        record = {"sku": here.sku, "qty": here.qty, "stable_id": sid};
        self.storage[sid] = record;
        here.persisted = True;
        print(f"    + {here.sku} qty={here.qty} -> {sid} (persisted)");
    }
}

walker Dumper {
    has depth: int = 0;

    can start with Root entry {
        print("graph dump:");
        print("root");
        visit [-->];
    }

    can dump with Warehouse entry {
        prefix = "  " * (self.depth + 1);
        print(f"{prefix}{here.name} (warehouse)");
        visit [-->];
    }

    can dump_item with Item entry {
        prefix = "  " * (self.depth + 1);
        sid = here.stable_id if here.stable_id else "(unassigned)";
        print(f"{prefix}{here.sku} qty={here.qty} id={sid}");
    }
}

with entry {
    w1 = Warehouse(name="North DC");
    w2 = Warehouse(name="South DC");

    root ++> w1;
    root ++> w2;

    w1 +>:Stocks(aisle="A1"):+> Item(sku="SKU-001", qty=42);
    w1 +>:Stocks(aisle="A2"):+> Item(sku="SKU-002", qty=7);
    w1 +>:Stocks(aisle="A3"):+> Item(sku="SKU-003", qty=120, persisted=False);

    w2 +>:Stocks(aisle="B1"):+> Item(sku="SKU-010", qty=15);
    w2 +>:Stocks(aisle="B2"):+> Item(sku="SKU-011", qty=88);

    auditor = Auditor();
    root spawn auditor;

    print("storage snapshot:");
    for sid in auditor.storage {
        rec = auditor.storage[sid];
        print(f"  {sid} -> sku={rec['sku']} qty={rec['qty']}");
    }

    print("");
    dumper = Dumper(depth=0);
    root spawn dumper;
}
```

```jac
"""Hiking trail: a chain of plain waypoints between trailhead and summit.

The waypoints carry no payload — they're pure graph topology. A hiker
walker travels the trail, counts each waypoint it passes, prints the
stop number, and emits a completion line once it has enough.
"""

node Waypoint {
    # Pure topology node: no fields, just a stop along the trail.
}

walker Hiker {
    has target: int = 3;
    has count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can hike with Waypoint entry {
        self.count += 1;
        print(f"Stop {self.count}");
        if self.count >= self.target {
            print(f"Summit reached after {self.count} stops!");
            disengage;
        }
        visit [-->] else {
            disengage;
        }
    }
}

with entry {
    root ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint();
    root spawn Hiker(target=4);
}
```

