"""Vet-clinic round: model pets as nodes and walk them with a vet, tracking shots given."""

node Pet {
    has name: str = "";
    has species: str = "";
    has needs_vaccine: bool = False;
}

walker Vet {
    has patient_names: list[str] = [];
    has shots_given: int = 0;

