```jac
"""Bug tracker: file tickets off a project node and capture the fresh ticket from the connection itself."""

node Ticket {
    has title: str = "";
    has priority: str = "normal";
    has available: bool = True;
}

walker TicketReporter {
    has count: int = 0;

    can start with Root entry {
        print(f"Filing tickets off project root");
        visit [-->];
    }

    can file with Ticket entry {
        self.count += 1;
        print(f"[FILED] {here.title} (priority={here.priority})");
        visit [-->];
    }
}

with entry {
    # Connect-and-grab: the connection expression itself returns the new Ticket.
    bug1 = root ++> Ticket(title="Login button broken", priority="high");
    bug2 = root ++> Ticket(title="Typo on landing page", priority="low");
    bug3 = root ++> Ticket(title="Crash on submit", priority="critical");

    # Print the freshly captured ticket immediately, no lookup query needed.
    print(f"Freshly filed: {bug1.title} ({bug1.priority})");
    print(f"Freshly filed: {bug2.title} ({bug2.priority})");
    print(f"Freshly filed: {bug3.title} ({bug3.priority})");

    # Walk the graph to report on every Ticket attached to root.
    reporter = root spawn TicketReporter();
    print(f"Total tickets filed: {reporter.count}");
}
```

```jac
"""Quiz app grader: walk quiz nodes, report strictly integer scores, and compute the class average."""

node Quiz {
    has student_name: str = "";
    has score: int = 0;
}

walker Grader {
    has scores: list[int] = [];
    has total: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can grade with Quiz entry {
        earned: int = here.score;
        self.scores.append(earned);
        self.total += earned;
        report earned;
        visit [-->];
    }
}

with entry {
    root ++> Quiz(student_name="Alice", score=88)
        ++> Quiz(student_name="Bob", score=92)
        ++> Quiz(student_name="Carol", score=76)
        ++> Quiz(student_name="Dave", score=84)
        ++> Quiz(student_name="Eve", score=95);

