```jac
"""Restaurant kitchen health-inspection walker.

Visits each station on the line (grill, fryer, cold prep), checks its
temperature against the 40 C safety threshold, and logs every station
visit. Both checks run at every station via a union ability.
"""

node Station {
    has name: str = "";
    has temp_c: float = 0.0;

    def is_violation() -> bool {
        return self.temp_c > 40.0;
    }
}

node Grill(Station) {
    has fuel_type: str = "gas";
    override def is_violation() -> bool {
        return self.temp_c > 40.0;
    }
}

node Fryer(Station) {
    has oil_level: float = 1.0;
    override def is_violation() -> bool {
        return self.temp_c > 40.0;
    }
}

node ColdPrep(Station) {
    has target_c: float = 4.0;
    override def is_violation() -> bool {
        return self.temp_c > 40.0;
    }
}

walker Inspector {
    has violation_count: int = 0;
    has log: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Grill | Fryer | ColdPrep entry {
        station_name = here.name;
        temperature = here.temp_c;
        self.log.append(f"Visited {station_name} at {temperature} C");
        print(f"Visited {station_name} at {temperature} C");

        if here.is_violation() {
            self.violation_count += 1;
            print(f"  VIOLATION: {station_name} exceeds 40 C threshold");
        } else {
            print(f"  OK: {station_name} within safe range");
        }

        visit [-->];
    }
}

with entry {
    grill = Grill(name="Grill", temp_c=180.0, fuel_type="gas");
    fryer = Fryer(name="Fryer", temp_c=165.0, oil_level=0.9);
    cold = ColdPrep(name="Cold Prep", temp_c=6.0, target_c=4.0);

    root ++> grill ++> fryer ++> cold;

    root spawn Inspector();

    print("Inspection complete");
}
