```jac
"""Warehouse robot: route plan per cell decides floor-roll or stair-climb.

The robot is spawned on the root, walks cell-by-cell along a typed
``Cell`` chain, and at every cell consults its plan to learn whether
the leg out of that cell is a ``FloorEdge`` (roll) or a ``StairEdge``
(climb). It logs each leg it actually traversed so the caller can see
the route the robot committed to.
"""

node Cell {
    has code: str = "";
    has floor_target: str = "";
    has stair_target: str = "";
}

edge FloorEdge {}
edge StairEdge {}

walker Robot {
    can start with Root entry {
        visit [-->];
    }

    can move with Cell entry {
        print(f"at cell {here.code}");
        # The plan says which leg is allowed from this cell.
        floor = [here ->:FloorEdge:->];
        stair = [here ->:StairEdge:->];
        if floor {
            visit floor;
        } elif stair {
            visit stair;
        } else {
            print("no allowed leg; stopping");
            disengage;
        }
    }
}

with entry {
    a = Cell(code="A", floor_target="B");
    b = Cell(code="B", floor_target="C");
    c = Cell(code="C", floor_target="D", stair_target="M");
    m = Cell(code="M", floor_target="N");
    n = Cell(code="N");

    root ++> a +>:FloorEdge:+> b +>:FloorEdge:+> c;
    c +>:StairEdge:+> m +>:FloorEdge:+> n;

    print("floor route:");
    Robot() spawn root;
    print("stair route from C:");
    Robot() spawn c;
}
```

