```jac
"""Journal share-link: walker arms a READ grant on a note; a second call revokes it back to owner-only."""

node Note {
    has title: str = "";
    has body: str = "";
    has owner: str = "self";
    has shareable: bool = False;
}

walker GrantRead {
    has reader: str = "guest";

    can start with Root entry {
        visit [-->];
    }

    can arm with Note entry {
        print(f"arming READ on '{here.title}' for {self.reader}");
        here.shareable = True;
        disengage;
    }
}

walker RevokeRead {
    can start with Root entry {
        visit [-->];
    }

    can revoke with Note entry {
        print(f"revoking READ on '{here.title}', back to owner-only");
        here.shareable = False;
        disengage;
    }
}

walker Inspector {
    has label: str = "before";

    can start with Root entry {
        visit [-->];
    }

    can peek with Note entry {
        flag = "SHARABLE" if here.shareable else "OWNER-ONLY";
        print(f"[{self.label}] {here.title} -> {flag}");
        disengage;
    }
}

with entry {
    diary = Note(title="Trip to Lisbon", body="pastel de nata every morning", owner="me");
    root ++> diary;

    print("=== initial state ===");
    Inspector(label="before") spawn root;

    print("=== arm share link ===");
    GrantRead(reader="alex") spawn diary;
    Inspector(label="armed") spawn root;

    print("=== revoke share link ===");
    RevokeRead() spawn diary;
    Inspector(label="after") spawn root;
}
