```jac
"""Turbo configuration graph: model global dependencies, env vars, and task
pipelines as nodes/edges, then walk them with a turbo walker that validates
cache invalidation rules across local and CI environments.
"""

# --- Node archetypes ----------------------------------------------------

node Config {
    has name: str = "";
    has schema: str = "";
}

node GlobalDep {
    has path: str = "";
    has kind: str = "file";
}

node GlobalEnv {
    has name: str = "";
    has affects_cache: bool = True;
}

node Task {
    has name: str = "";
    has concurrency: int = 0;
    has has_env_override: bool = False;
}

node EnvVar {
    has name: str = "";
    has value: str = "";
}

# --- Edge archetypes ----------------------------------------------------

edge Requires {
    has optional: bool = False;
}

edge Invalidates {
    has reason: str = "";
}

edge RunsIn {
    has env_name: str = "";
}

# --- Walker -------------------------------------------------------------

walker TurboAuditor {
    has visited: list = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_config with Config entry {
        self.visited.append(here.name);
        print(f"[CONFIG] {here.name} schema={here.schema}");
        visit [-->];
    }

    can audit_dep with GlobalDep entry {
        self.visited.append(here.path);
        kind_label = "env-local" if "local" in here.path else "config";
        print(f"  [DEP ] {here.path}  ({here.kind}, {kind_label})");
        visit [-->];
    }

    can audit_env with GlobalEnv entry {
        self.visited.append(here.name);
        flag = "CACHE-AFFECTING" if here.affects_cache else "passthrough";
        print(f"  [ENV ] {here.name} -> {flag}");
        visit [-->];
    }

    can audit_task with Task entry {
        self.visited.append(here.name);
        conc = here.concurrency;
        env_override = here.has_env_override;
        print(f"  [TASK] {here.name}  concurrency={conc}  env_override={env_override}");
        visit [-->];
    }

    can audit_var with EnvVar entry {
        self.visited.append(here.name);
        print(f"    [VAR ] {here.name}={here.value}");
        visit [-->];
    }
}

# --- Demo wiring --------------------------------------------------------

with entry {
    cfg = Config(name="turbo.json", schema="https://turbo.build/schema.json");

    dep_env_local = GlobalDep(path="**/.env.*local", kind="dotenv");
    dep_tsconfig  = GlobalDep(path="**/tsconfig.json", kind="tsconfig");
    dep_nvmrc     = GlobalDep(path=".nvmrc", kind="nvmrc");
    dep_lock      = GlobalDep(path="pnpm-lock.yaml", kind="lockfile");

    env_node_env = GlobalEnv(name="NODE_ENV");
    env_ci       = GlobalEnv(name="CI");
    env_gha      = GlobalEnv(name="GITHUB_ACTIONS");
    env_log      = GlobalEnv(name="LOG_LEVEL", affects_cache=False);

    task_build       = Task(name="build", concurrency=2);
    task_test        = Task(name="test", concurrency=2, has_env_override=True);
    task_mutation    = Task(name="test:mutation", concurrency=1);

    var_timeout = EnvVar(name="TEST_TIMEOUT", value="30000");
    var_node    = EnvVar(name="NODE_ENV", value="test");

    # Wire the graph: root -> config -> global deps + envs -> tasks -> vars
    root ++> cfg;

    cfg +>:Requires:+> dep_env_local;
    cfg +>:Requires:+> dep_tsconfig;
    cfg +>:Requires:+> dep_nvmrc;
    cfg +>:Requires:+> dep_lock;

    cfg +>:Requires:+> env_node_env;
    cfg +>:Requires:+> env_ci;
    cfg +>:Requires:+> env_gha;
    cfg +>:Requires:+> env_log;

    cfg +>:RunsIn(env_name="ci"):+> task_build;
    cfg +>:RunsIn(env_name="ci"):+> task_test;
    cfg +>:RunsIn(env_name="ci"):+> task_mutation;

    task_test +>:Requires(optional=True):+> var_timeout;
    task_test +>:Requires(optional=False):+> var_node;

    # Cache invalidation edges: lockfile/env changes bust everything.
    dep_lock    +>:Invalidates(reason="deps changed"):+> task_build;
    dep_env_local +>:Invalidates(reason="env-local"):+> task_test;

    auditor = TurboAuditor();
    print("=== Turbo Auditor traversal ===");
    root spawn auditor;

    print("\n=== Summary ===");
    print(f"Visited {len(auditor.visited)} nodes");
}
```

