```jac
"""Subagent scope enforcement: modeling the PowerShell $home collision incident.

The bug: a read-only subagent recursively deletes %USERPROFILE% because a
cleanup command collides PowerShell's read-only automatic $HOME variable
with a local $home assignment, leaving $home resolved to the real user
profile. The destructive recursion is not interrupted by the language-level
non-terminating error.

This program models the essential scenario natively in Jac:

  - A delegation hierarchy (Project -> Subagent -> Command -> Path) connected
    by typed edges (DelegatesTo, Issues, Targets).
  - A SubagentRole node carrying the scope/permission fields the issue
    describes (read_only, approval_policy, action_preference).
  - A Path node with a sensitive flag and a canonical-resolved payload,
    representing the directory tree that gets walked and pruned.
  - A ScopeAuditor walker that descends the delegation chain, classifies
    commands as in-scope or out-of-scope, and a CascadePurge walker that
    performs the recursive prune -- but is blocked at the read-only root
    because the read-only flag is honored before any child is visited.

The whole point: cascade-deletion machinery must respect the scope that
spawned it, not just rely on a downstream command's variable hygiene.
"""

node SubagentRole {
    has role_name: str = "";
    has read_only: bool = True;
    has approval_policy: str = "Never";
    has action_preference: str = "Continue";  # PowerShell $ErrorActionPreference
}

node Command {
    has label: str = "";
    has uses_unsafe_variable: bool = False;   # the $home collision
    has has_terminating_errors: bool = False; # $ErrorActionPreference = 'Stop'
    has is_destructive: bool = False;          # Remove-Item -Recurse -Force
}

node Path {
    has pname: str = "";
    has is_sensitive_root: bool = False;      # the %USERPROFILE% boundary
    has canonical_resolved: bool = False;     # canonical-path guard
}

edge DelegatesTo {
    has granted_at: str = "";
}

edge Issues {
    has seq: int = 0;
}

edge Targets {
    has depth: int = 0;
}

walker ScopeAuditor {
    has violations: list[str] = [];
    has visited: list[str] = [];   # explicit cycle / re-entry guard

    can start with Root entry {
        visit [->:DelegatesTo:->];
    }

    can descend with SubagentRole entry {
        self.visited.append(here.role_name);
        print(f"[audit] role={here.role_name} read_only={here.read_only} "
              f"approval={here.approval_policy} err_pref={here.action_preference}");
        visit [->:Issues:->];
    }

    can inspect_cmd with Command entry {
        # The original PowerShell $home collision signature: local $home
        # collides with read-only automatic $HOME, leaving $home resolved
        # to the real user profile while still permitting execution.
        if here.uses_unsafe_variable and not here.has_terminating_errors {
            note = f"variable-collision risk on cmd '{here.label}'";
            self.violations.append(note);
            print(f"  [violation] {note}");
        } else {
            print(f"  [ok] cmd '{here.label}'");
        }
        visit [->:Targets:->];
    }

    can mark_path with Path entry {
        if here.is_sensitive_root and not here.canonical_resolved {
            note = f"sensitive root '{here.pname}' hit without canonical guard";
            self.violations.append(note);
            print(f"  [violation] {note}");
        } else {
            print(f"  [ok] path '{here.pname}'");
        }
        visit [->:Targets:->];
    }
}

walker CascadePurge {
    has pruned: list[str] = [];
    has blocked: bool = False;

    can start with Root entry {
        visit [->:DelegatesTo:->];
    }

    can enter_role with SubagentRole entry {
        # The domain invariant the issue is really about: a read-only
        # subagent must not cascade-delete anything, regardless of what
        # downstream commands try to do. This is the cycle/scope guard.
        if here.read_only {
            self.blocked = True;
            print(f"[purge] BLOCKED at role={here.role_name} (read_only)");
            disengage;
        }
        print(f"[purge] entering role={here.role_name}");
        visit [->:Issues:->];
    }

    can enter_cmd with Command entry {
        if here.is_destructive {
            self.pruned.append(here.label);
            print(f"[purge] pruning via cmd='{here.label}'");
        }
        visit [->:Targets:->];
    }

    can enter_path with Path entry {
        # Even if a destructive command slipped through, the sensitive
        # root boundary is a hard stop -- mirroring the canonical-path
        # guard the issue says was missing.
        if here.is_sensitive_root and not here.canonical_resolved {
            print(f"[purge] BLOCKED at sensitive path '{here.pname}'");
            disengage;
        }
        self.pruned.append(here.pname);
        print(f"[purge] removed {here.pname}");
        visit [->:Targets:->];
    }
}

with entry {
    # --- Graph wiring ---
    read_only_role = SubagentRole(
        role_name="audit-subagent",
        read_only=True,
        approval_policy="Never",
        action_preference="Continue"
    );

    # The offending compound command: local $home collides with read-only
    # $HOME, no terminating error preference, recursive destructive prune.
    bad_cmd = Command(
        label="cleanup-temp",
        uses_unsafe_variable=True,
        has_terminating_errors=False,
        is_destructive=True
    );

    # Sensitive paths under %USERPROFILE% the recursion would walk into.
    user_profile = Path(pname="%USERPROFILE%", is_sensitive_root=True, canonical_resolved=False);
    codex_dir    = Path(pname=".codex",        is_sensitive_root=False);
    appdata      = Path(pname="AppData",       is_sensitive_root=False);
    documents    = Path(pname="Documents",     is_sensitive_root=False);

    # Delegation: Root -> read_only subagent -> compound command -> paths.
    root +>:DelegatesTo(granted_at="2026-07-13"):+> read_only_role;
    read_only_role +>:Issues(seq=1):+> bad_cmd;
    bad_cmd +>:Targets(depth=0):+> user_profile;
    user_profile +>:Targets(depth=1):+> codex_dir;
    codex_dir    +>:Targets(depth=2):+> appdata;
    appdata      +>:Targets(depth=3):+> documents;

    # --- Demo 1: scope audit ---
    auditor = ScopeAuditor();
    root spawn auditor;
    print(f"[audit] total violations recorded: {len(auditor.violations)}");
    for v in auditor.violations {
        print(f"  - {v}");
    }

    # --- Demo 2: cascade purge that must be blocked by scope ---
    purger = CascadePurge();
    root spawn purger;
    print(f"[purge] blocked={purger.blocked} pruned={purger.pruned}");
}
```

