```jac
"""Online store checkout: dispatch on product type, itemized receipt.

The cart holds mixed products (paper book, digital book, electronics,
clothing). A single Checkout walker visits each item; a union ability on
the shared Product base reacts to the item's concrete subtype and applies
the right shipping/handling rule. Totals accumulate on the walker and a
single itemized receipt prints on disengage.
"""

node Product {
    has name: str = "";
    has price: float = 0.0;

    def shipping_cost() -> float {
        return 0.0;
    }

    def handling_label() -> str {
        return "standard";
    }
}

node PaperBook(Product) {
    has weight_lb: float = 1.0;

    override def shipping_cost() -> float {
        return 2.50 + 0.75 * self.weight_lb;
    }

    override def handling_label() -> str {
        return "ground";
    }
}

node DigitalBook(Product) {
    has file_size_mb: float = 5.0;

    override def shipping_cost() -> float {
        return 0.0;
    }

    override def handling_label() -> str {
        return f"download ({self.file_size_mb} MB)";
    }
}

node Electronics(Product) {
    has warranty_years: int = 1;
    has insured: bool = True;

    override def shipping_cost() -> float {
        base = 7.99;
        insurance = 4.50 if self.insured else 0.0;
        return base + insurance + 1.0 * self.warranty_years;
    }

    override def handling_label() -> str {
        return f"insured ({self.warranty_years}yr warranty)";
    }
}

node Clothing(Product) {
    has size: str = "M";

    override def shipping_cost() -> float {
        return 3.95;
    }

    override def handling_label() -> str {
        return f"apparel size {self.size}";
    }
}

walker Checkout {
    has subtotal: float = 0.0;
    has shipping_total: float = 0.0;
    has line_count: int = 0;

    can start with Root entry {
        print("=== CHECKOUT ===");
        visit [-->];
    }

    can ring with PaperBook | DigitalBook | Electronics | Clothing entry {
        item_cost = here.price;
        ship = here.shipping_cost();
        method = here.handling_label();
        self.subtotal = self.subtotal + item_cost;
        self.shipping_total = self.shipping_total + ship;
        self.line_count = self.line_count + 1;
        print(
            f"  [{self.line_count}] {here.name} "
            f"(${item_cost:.2f}) + ship ${ship:.2f} ({method})"
        );
        visit [-->];
    }
}

with entry {
    root ++> PaperBook(name="The Pragmatic Programmer", price=29.99, weight_lb=1.4)
        ++> DigitalBook(name="Refactoring (eBook)", price=22.50, file_size_mb=12.0)
        ++> Electronics(name="Wireless Headphones", price=149.00, warranty_years=2, insured=True)
        ++> Clothing(name="Cotton Tee", price=18.75, size="L");

    cashier = Checkout();
    root spawn cashier;

    grand = cashier.subtotal + cashier.shipping_total;
    print("---");
    print(f"Subtotal: ${cashier.subtotal:.2f}");
    print(f"Shipping: ${cashier.shipping_total:.2f}");
    print(f"TOTAL:    ${grand:.2f}");
}
