```jac
"""Tiny dungeon crawler: chained rooms with a single treasure vault.

A Hunter walker traverses the dungeon one room at a time, counting
rooms inspected. The moment it steps into the vault room the entire
search ends immediately — no rooms past the vault are ever visited.
"""

node Room {
    has name: str = "";
    has is_vault: bool = False;
}

walker Hunter {
    has rooms_inspected: int = 0;
    has found_treasure: bool = False;
    has vault_name: str = "";

    can start with Root entry {
        visit [-->];
    }

    can explore with Room entry {
        if self.found_treasure {
            # Treasure was found earlier in the chain; halt immediately
            # so no rooms past the vault are ever visited.
            disengage;
        }
        self.rooms_inspected += 1;
        if here.is_vault {
            self.found_treasure = True;
            self.vault_name = here.name;
            print(f"Treasure found in '{here.name}' after inspecting "
                  f"{self.rooms_inspected} room(s). Halting search.");
            disengage;
        }
        print(f"Inspected '{here.name}' — empty.");
        visit [-->];
    }
}

with entry {
    dungeon = root;
    dungeon ++> Room(name="Foyer")
        ++> Room(name="Antechamber")
        ++> Room(name="Hall of Echoes")
        ++> Room(name="Vault of Ages", is_vault=True)
        ++> Room(name="Hidden Alcove")
        ++> Room(name="Forgotten Crypt");

    hunter = Hunter();
    root spawn hunter;

    if hunter.found_treasure {
        print(f"Hunter report: found '{hunter.vault_name}' in "
              f"{hunter.rooms_inspected} room(s); rooms past the vault "
              f"were never entered.");
    } else {
        print(f"Hunter report: no vault found, "
              f"{hunter.rooms_inspected} room(s) inspected.");
    }
}
