```jac
"""Streaming transcript pipeline: model the O(n)-per-delta cascade as a graph walk.

Each streaming text delta in the web shell recomputes four layers over the
whole transcript. We model that as a typed chain of pipeline nodes
(Blocks -> MergedMessages -> DisplayItems -> VisibleItems) connected by
typed edges, and let a walker traverse the pipeline exactly the way React
would: one delta, one full walk of the chain, O(n) per stage. A second
walker shows that a tail-only fast path (append-only) only revisits the
last message instead of the whole list.
"""

# ---------- Entity archetypes --------------------------------------------------

node Message {
    has role: str = "";
    has content: str = "";
    has tokens: int = 0;
}

node Blocks {
    has label: str = "blocks";
}

node MergedMessages {
    has label: str = "merged";
}

node DisplayItems {
    has label: str = "display";
}

node VisibleItems {
    has label: str = "visible";
}

# ---------- Typed edges (each layer reads from the previous one) ---------------

edge Feeds { }

# ---------- Walker 1: full-pipeline recompute (the O(n) pain point) -----------

walker FullPipelineReprocess {
    has stream_delta: str = "";
    has work_per_stage: int = 0;
    has stages_visited: list[str] = [];

    can start with Blocks entry {
        self.stages_visited.append(here.label);
        # Stage 1 cost: O(n) over the full transcript.
        msgs = [-->[?:Message]];
        for m in msgs {
            self.work_per_stage += m.tokens;
        }
        visit [->:Feeds:->];
    }

    can merge with MergedMessages entry {
        self.stages_visited.append(here.label);
        # Stage 2 cost: another O(n) over the merged view.
        msgs = [-->[?:Message]];
        for m in msgs {
            self.work_per_stage += m.tokens;
        }
        visit [->:Feeds:->];
    }

    can render with DisplayItems entry {
        self.stages_visited.append(here.label);
        # Stage 3 cost: yet another O(n).
        msgs = [-->[?:Message]];
        for m in msgs {
            self.work_per_stage += m.tokens;
        }
        visit [->:Feeds:->];
    }

    can clip with VisibleItems entry {
        self.stages_visited.append(here.label);
        # Stage 4 cost: the final O(n) cull to the visible window.
        msgs = [-->[?:Message]];
        for m in msgs {
            self.work_per_stage += m.tokens;
        }
    }
}

# ---------- Walker 2: tail-only fast path (the suggested fix) ------------------

walker TailOnlyAppend {
    has appended_to_tail: bool = False;

    can start with Blocks entry {
        # Only the last message changed; walk the same four stages but
        # touch one node, not the whole transcript.
        msgs = [-->[?:Message]];
        if len(msgs) > 0 {
            tail = msgs[-1];
            tail.content = tail.content + "+1tok";
            tail.tokens = tail.tokens + 1;
            self.appended_to_tail = True;
        }
        visit [->:Feeds:->];
    }

    can merge with MergedMessages entry {
        visit [->:Feeds:->];
    }
    can render with DisplayItems entry {
        visit [->:Feeds:->];
    }
    can clip with VisibleItems entry {
        # End of the chain.
    }
}

# ---------- Demo wiring -------------------------------------------------------

with entry {
    # Build a transcript: a long history plus one streaming tail message.
    history = [
        Message(role="user", content="hi", tokens=2),
        Message(role="assistant", content="hello", tokens=3),
        Message(role="user", content="explain graphs", tokens=4),
        Message(role="assistant", content="sure", tokens=5),
        Message(role="user", content="walk an example", tokens=6),
        Message(role="assistant", content="ok", tokens=7),
    ];
    streaming_tail = Message(role="assistant", content="typing", tokens=1);

    blocks = Blocks();
    merged = MergedMessages();
    display = DisplayItems();
    visible = VisibleItems();

    # Chain the pipeline stages with typed Feeds edges.
    blocks +>:Feeds:+> merged +>:Feeds:+> display +>:Feeds:+> visible;

    # Attach the transcript (history + streaming tail) under each stage so the
    # walker can iterate over messages the same way the React layers would.
    for m in history {
        blocks   ++> m;
        merged   ++> m;
        display  ++> m;
        visible  ++> m;
    }
    blocks   ++> streaming_tail;
    merged   ++> streaming_tail;
    display  ++> streaming_tail;
    visible  ++> streaming_tail;

    print(f"transcript length: {len(history) + 1} messages");

    # 1) The pain point: one streaming delta triggers a full O(n) walk.
    pain = FullPipelineReprocess(stream_delta="+1tok");
    blocks spawn pain;
    print(
        f"FullPipelineReprocess walked {pain.stages_visited} stages "
        f"and did {pain.work_per_stage} token-units of work for ONE delta"
    );

    # 2) The proposed fix: a tail-only walker that touches just the tail.
    fix = TailOnlyAppend();
    blocks spawn fix;
    print(
        f"TailOnlyAppend appended_to_tail={fix.appended_to_tail}; "
        f"only the last message was mutated, no full-list walks"
    );
}
```

