```jac
"""Hosted review workflow status mismatch: model the workflow→parser status contract.

The hosted review workflow writes ``status: "timeout"`` when the ``timeout``
command returns rc 124/137, but the control-plane job result parser only
accepts ``timed_out``. The mismatch causes the control plane to reject the
callback payload as ``invalid review result status "timeout"``. This demo
models the canonical statuses, the workflow emitter, and a status auditor
walker that traverses the emitted artifacts to verify the contract.
"""

# ---- Canonical statuses (control-plane vocabulary) ------------------------
node Approved { has reviewer: str = ""; }
node ChangesRequested { has reviewer: str = ""; }
node Failed { has reason: str = ""; }
node TimedOut { has after_seconds: int = 0; }
node Unparseable { has raw: str = ""; }

# Anything not matching a canonical status collapses to this.
node Unknown { has raw: str = ""; }

# ---- Workflow artifact nodes ----------------------------------------------
node Workflow {
    has name: str = "";
}

node ResultFile {
    has path: str = "/tmp/herd-review-command-result.json";
    has payload: str = "";
}

node ReportStep {
    has allow_list: str = "";
}

# ---- Typed edges: who produced what ---------------------------------------
edge Emits {
    has at: str = "";
}

edge ParsedBy {
    has at: str = "";
}

# ---- Walker: traverse a workflow and audit its emitted statuses -----------
walker Auditor {
    has findings: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Workflow entry {
        print(f"Auditing workflow: {here.name}");
        visit [->:Emits:->];
    }

    can inspect_result with ResultFile entry {
        # Naively extract the ``status`` value from the JSON payload.
        payload = here.payload;
        start = payload.find('"status":"') + len('"status":"');
        end = payload.find('"', start);
        status_value = payload[start:end] if start >= len('"status":"') else "";
        verdict = "ok" if status_value == "timed_out" else "MISMATCH";
        self.findings.append(f"{here.path} -> {status_value} ({verdict})");
        print(f"  result file {here.path}: status={status_value} [{verdict}]");
        visit [->:ParsedBy:->];
    }

    can inspect_parser with ReportStep entry {
        # Verify the report step's shell ``case`` allow-list mentions timed_out.
        allow = here.allow_list;
        ok = ("timed_out" in allow) and ("timeout" not in allow or "timeout" in allow and "timed_out" in allow);
        verdict = "ok" if ok else "MISMATCH";
        self.findings.append(f"report allow-list -> '{allow}' ({verdict})");
        print(f"  report allow-list: '{allow}' [{verdict}]");
    }
}

with entry {
    # Build a workflow that emits the BROKEN payload (``timeout`` instead of
    # ``timed_out``) and an allow-list that still admits ``timeout``.
    broken_wf = Workflow(name="herd-review (pre-fix)");
    bad_result = ResultFile(
        payload='{"status":"timeout","summary":"Herd Review timed out after 900s"}'
    );
    bad_report = ReportStep(
        allow_list="approved|changes_requested|failed|timeout|unparseable"
    );
    broken_wf +>:Emits(at="workflow_step"):+> bad_result;
    broken_wf +>:Emits(at="workflow_step"):+> bad_report;
    bad_result +>:ParsedBy(at="controlplane"):+> bad_report;

    # Build a workflow that emits the CORRECT payload and allow-list.
    fixed_wf = Workflow(name="herd-review (post-fix)");
    good_result = ResultFile(
        payload='{"status":"timed_out","summary":"Herd Review timed out after 900s"}'
    );
    good_report = ReportStep(
        allow_list="approved|changes_requested|failed|timed_out|unparseable"
    );
    fixed_wf +>:Emits(at="workflow_step"):+> good_result;
    fixed_wf +>:Emits(at="workflow_step"):+> good_report;
    good_result +>:ParsedBy(at="controlplane"):+> good_report;

    root ++> broken_wf ++> fixed_wf;

    auditor = Auditor();
    root spawn auditor;

    print("\n--- audit summary ---");
    for finding in auditor.findings {
        print(finding);
    }
}
```

```jac
"""Order auditor: invalid orders are skipped, fraud-flagged orders halt the walk.

Demonstrates both flavors of early return in a single walker: `continue`-style
skipping of invalid orders (the audit moves on to the next sibling) and an
immediate `disengage` when a fraud flag is raised.
"""

node Order {
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    has halted: bool = False;

    can start with Root entry {
        print("Audit begins");
        visit [-->] else { disengage; }
    }

    can audit with Order entry {
        # Fraud check: halt the whole walk immediately.
        if here.fraud {
            print(f"HALT on order ${here.amount}: fraud flag raised");
            self.halted = True;
            disengage;
        }

        # Validity check: skip this order, keep auditing.
        if not here.valid {
            print(f"SKIP order ${here.amount}: invalid");
            visit [-->];
            return;
        }

        # Healthy order: record it.
        print(f"OK   order ${here.amount}");
        visit [-->];
    }
}

with entry {
    root ++> Order(amount=120.0, valid=True, fraud=False)
        ++> Order(amount=55.0, valid=False, fraud=False)
        ++> Order(amount=300.0, valid=True, fraud=False)
        ++> Order(amount=999.0, valid=True, fraud=True)
        ++> Order(amount=42.0, valid=True, fraud=False);

    auditor = OrderAuditor();
    root spawn auditor;

    if auditor.halted {
        print("Audit terminated early due to fraud");
    } else {
        print("Audit completed cleanly");
    }
}
```

