```jac
"""Pet-or-People social graph: a walker recommends adult-human friends only.

Profiles may be human (with an age) or pet (no age concept). The walker
visits every profile reachable from each person through the ``Friends``
edge, counts the raw neighbour total, then filters out pet nodes and
minors (age < 18), reporting the surviving adult-human suggestions.
"""

node Profile {
    has name: str = "";
    has age: int = 0;
    has species: str = "human";

    def is_human() -> bool {
        return self.species == "human";
    }

    def is_adult() -> bool {
        return self.is_human() and self.age >= 18;
    }

    def is_eligible_friend() -> bool {
        return self.is_adult();
    }
}

edge Friends {
    has years_known: int = 0;
}

walker Recommender {
    has raw_count: int = 0;
    has eligible_count: int = 0;
    has person_name: str = "";

    can start with Root entry {
        visit [-->];
    }

    can recommend with Profile entry {
        if not here.is_human() {
            return;
        }
        self.person_name = here.name;
        self.raw_count = 0;
        self.eligible_count = 0;
        for n in [->:Friends:->] {
            self.raw_count += 1;
            if n.is_eligible_friend() {
                self.eligible_count += 1;
            }
        }
        print(
            f"{self.person_name}: raw neighbours={self.raw_count}, "
            f"adult-human suggestions={self.eligible_count}"
        );
    }
}

with entry {
    alice = Profile(name="Alice", age=30);
    bob = Profile(name="Bob", age=25);
    carol = Profile(name="Carol", age=17);
    rex = Profile(name="Rex", species="pet");
    whiskers = Profile(name="Whiskers", species="pet");

    alice +>:Friends(years_known=5):+> bob;
    alice +>:Friends(years_known=3):+> carol;
    alice +>:Friends(years_known=7):+> rex;
    alice +>:Friends(years_known=2):+> whiskers;

    bob +>:Friends(years_known=10):+> alice;
    bob +>:Friends(years_known=1):+> rex;

    root ++> alice ++> bob;
    root ++> carol;
    root ++> rex;
    root ++> whiskers;

    root spawn Recommender();
}
