```jac
"""Build-system cycle detector.

Modules list the modules they depend on. A walker follows dependencies
across typed ``DependsOn`` edges and reports any module that revisits
itself, printing the exact cycle path that triggered the bug.
"""

node Module {
    has name: str = "";
    has depends_on: list[str] = [];
}

edge DependsOn {
    has target_name: str = "";
}

walker CycleHunter {
    has path: list[Module] = [];
    has names: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can hunt with Module entry {
        # Cycle guard: explicit, because walkers don't dedupe.
        if here.name in self.names {
            cycle_start = self.names.index(here.name);
            cycle_names = self.names[cycle_start:] + [here.name];
            print("CYCLE DETECTED: " + " -> ".join(cycle_names));
            disengage;
        }

        self.path = self.path + [here];
        self.names = self.names + [here.name];

        # Find outgoing DependsOn edges by target name.
        outgoing = [e for e in [->:DependsOn:->] if True];
        next_edges = [here->:DependsOn:->];
        if not next_edges {
            disengage;
        }

        next_node = next_edges[0];
        print(f"  {self.names[-1]} depends on {next_node.name}");
        visit next_node;
    }
}

with entry {
    # Deliberately broken graph:
    #   app -> utils -> core -> utils (cycle: utils -> core -> utils)
    app = Module(name="app");
    utils = Module(name="utils");
    core = Module(name="core");
    ui = Module(name="ui");
    db = Module(name="db");

    root ++> app;
    root ++> ui;
    root ++> db;

    app +>:DependsOn(target_name="utils"):+> utils;
    utils +>:DependsOn(target_name="core"):+> core;
    core +>:DependsOn(target_name="utils"):+> utils;
    ui +>:DependsOn(target_name="app"):+> app;
    db +>:DependsOn(target_name="core"):+> core;

    print("=== Scanning app and its dependencies ===");
    root spawn CycleHunter();
}
