"""Weather sweep: stations report temperature as the walker passes, then summarize."""

node Station {
    has location: str = "";
    has celsius: float = 0.0;
}

walker Sweep {
    has readings: list[tuple[str, float]] = [];
    has mins: list[tuple[str, float]] = [];
    has maxs: list[tuple[str, float]] = [];

    can start with Root entry {
        visit [-->];
    }

    can read with Station entry {
        print(f"  reading {here.celsius}C at {here.location}");
        self.readings.append((here.location, here.celsius));
        if len(self.mins) == 0 or here.celsius < self.mins[0][1] {
            self.mins = [(here.location, here.celsius)];
        } elif here.celsius == self.mins[0][1] {
            self.mins.append((here.location, here.celsius));
        }
        if len(self.maxs) == 0 or here.celsius > self.maxs[0][1] {
            self.maxs = [(here.location, here.celsius)];
        } elif here.celsius == self.maxs[0][1] {
            self.maxs.append((here.location, here.celsius));
        }
        visit [-->];
    }
}

with entry {
    root ++> Station(location="North", celsius=12.5)
        ++> Station(location="East", celsius=17.0)
        ++> Station(location="South", celsius=23.8)
        ++> Station(location="West", celsius=9.2)
        ++> Station(location="Summit", celsius=-3.0);

    sweeper = Sweep();
    root spawn sweeper;

    print("\nAll readings:");
    for (loc, temp) in sweeper.readings {
        print(f"  {loc}: {temp}C");
    }

    min_loc = sweeper.mins[0][0];
    min_val = sweeper.mins[0][1];
    max_loc = sweeper.maxs[0][0];
    max_val = sweeper.maxs[0][1];
    print(f"\nMin: {min_val}C at {min_loc}");
    print(f"Max: {max_val}C at {max_loc}");
