```jac
"""Packaging-shape benchmark registry.

Models the kernal-api Phase-0 measurement protocol: a benchmark protocol
records its toolchain, host, commands, feature sets, and repeated
measurements. Candidate packaging shapes (monolithic facade, coarse
private crates, release amalgamation) are tracked as benchmarked
artifacts; feature capabilities are gated modules whose dependency
trees must omit when disabled. A walker audits that disabled
capabilities truly leave the resolved graph.
"""

node Host {
    has label: str = "";
    has cpu: str = "";
    has memory_gb: int = 0;
}

node Toolchain {
    has name: str = "";
    has version: str = "";
    has soldr_version: str = "";
    has zccache_version: str = "";
}

node Capability {
    has name: str = "";
    has enabled: bool = False;
    has deps_resolved: int = 0;
}

node PackagingShape {
    has kind: str = "";
    has cohesive: bool = False;
    has publish: bool = True;
    has hidden_behind_facade: bool = False;
    has clean_time_s: float = 0.0;
    has incremental_crit_s: float = 0.0;
    has peak_mem_mb: float = 0.0;
    has cache_hit_ratio: float = 0.0;
    has artifact_kb: int = 0;
}

edge ToolchainOf {}
edge HostOf {}
edge CapabilityOf {}
edge MeasuredOn {}
edge DisabledOmits {}

walker Benchmark {
    has protocol_id: str = "phase0-#3";
    has repeats: int = 0;
    has clean_violations: int = 0;
    has incr_violations: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit_toolchain with Toolchain entry {
        print(f"[toolchain] {here.name} {here.version} "
              f"(soldr={here.soldr_version}, zccache={here.zccache_version})");
        visit [-->];
    }

    can audit_host with Host entry {
        print(f"[host] {here.label}: {here.cpu}, {here.memory_gb}GB");
        visit [-->];
    }

    can audit_capability with Capability entry {
        verdict = "OK";
        if (not here.enabled) and (here.deps_resolved != 0) {
            verdict = "VIOLATION";
            self.clean_violations += 1;
        } elif here.enabled {
            self.repeats += 1;
        }
        print(f"[capability] {here.name} enabled={here.enabled} "
              f"deps_resolved={here.deps_resolved} -> {verdict}");
        visit [-->];
    }

    can audit_shape with PackagingShape entry {
        verdict = "OK";
        is_private = (not here.publish);
        if is_private and ((not here.cohesive) or (not here.hidden_behind_facade)) {
            verdict = "VIOLATION";
            self.incr_violations += 1;
        }
        print(f"[shape] {here.kind}: cohesive={here.cohesive}, "
              f"publish={here.publish}, hidden={here.hidden_behind_facade} "
              f"-> {verdict}");
        print(f"        clean={here.clean_time_s}s "
              f"incr={here.incremental_crit_s}s "
              f"peak={here.peak_mem_mb}MB "
              f"cache_hit={here.cache_hit_ratio:.2f} "
              f"artifact={here.artifact_kb}KB");
        visit [-->];
    }
}

walker RedGreenAudit {
    has disabled_leaks: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can scan_capability with Capability entry {
        if (not here.enabled) and (here.deps_resolved != 0) {
            self.disabled_leaks.append(here.name);
        }
        visit [-->];
    }

    can scan_shape with PackagingShape entry {
        visit [-->];
    }
}

with entry {
    host = Host(label="ci-linux-x64", cpu="amd-epyc-7763", memory_gb=64);
    tc = Toolchain(name="rustc", version="1.79.0",
                   soldr_version="1.4.2", zccache_version="0.8.0");
    proc_cap = Capability(name="process", enabled=True, deps_resolved=3);
    fs_cap = Capability(name="filesystem", enabled=True, deps_resolved=2);
    ipc_cap = Capability(name="ipc", enabled=False, deps_resolved=0);
    broker_cap = Capability(name="broker", enabled=False, deps_resolved=0);

    mono = PackagingShape(kind="monolithic-facade", cohesive=True,
                          publish=True, hidden_behind_facade=True,
                          clean_time_s=128.4, incremental_crit_s=4.1,
                          peak_mem_mb=2140.0, cache_hit_ratio=0.62,
                          artifact_kb=18400);
    coarse = PackagingShape(kind="coarse-private-crates", cohesive=True,
                            publish=False, hidden_behind_facade=True,
                            clean_time_s=96.7, incremental_crit_s=2.9,
                            peak_mem_mb=1620.0, cache_hit_ratio=0.78,
                            artifact_kb=18300);
    amalg = PackagingShape(kind="release-amalgamation", cohesive=True,
                           publish=True, hidden_behind_facade=True,
                           clean_time_s=141.2, incremental_crit_s=5.4,
                           peak_mem_mb=2380.0, cache_hit_ratio=0.55,
                           artifact_kb=18600);

    root +>:ToolchainOf:+> tc;
    root +>:HostOf:+> host;
    root +>:CapabilityOf:+> proc_cap;
    root +>:CapabilityOf:+> fs_cap;
    root +>:CapabilityOf:+> ipc_cap;
    root +>:CapabilityOf:+> broker_cap;
    root +>:MeasuredOn:+> mono;
    root +>:MeasuredOn:+> coarse;
    root +>:MeasuredOn:+> amalg;

    ipc_cap +>:DisabledOmits:+> Capability(name="ipc-dep-internal",
                                           enabled=False, deps_resolved=0);
    broker_cap +>:DisabledOmits:+> Capability(name="broker-dep-internal",
                                             enabled=False, deps_resolved=0);

    print(f"=== benchmark protocol phase0-#3 ===");
    root spawn Benchmark();

    print("=== red->green dependency audit ===");
    auditor = RedGreenAudit();
    root spawn auditor;
    if auditor.disabled_leaks {
        print(f"LEAKS: {auditor.disabled_leaks}");
    } else {
        print("disabled capabilities omit their trees cleanly");
    }

    selection = "monolithic-facade";
    if (coarse.clean_time_s < mono.clean_time_s) and coarse.cohesive and (not coarse.publish) {
        selection = "coarse-private-crates";
    }
    print(f"=== selection (ARCHITECTURE.md) -> {selection} ===");
}
