```jac
"""Scoped catalog view: label-level access control via snapshot scoping.

Models the SparrowDB issue's core scenario — a hand-rolled label catalog
with 86 resolution sites that no longer needs per-call authorization
checks because the snapshot itself is scoped to the principal's permitted
labels. A single materialization path applies visibility, so callers
cannot bypass it. The leak surface (counts, existence, label enumeration)
is handled at the same chokepoint.
"""

# ---------- entity archetypes ----------

node Label {
    has name: str = "";
    has kind: str = "";
}

node Row {
    has label_name: str = "";
    has tombstoned: bool = False;
}

# An edge carrying a typed relationship: a Row belongs to a Label,
# and that membership is what the catalog will allow or deny.
edge MemberOf { }

# A typed edge representing the "execute a query" relationship from
# the principal (Root) into a snapshot — the chokepoint at which
# scoping is enforced.
edge Executes { has query_kind: str = "READ"; }

# ---------- the principal ----------

node Principal {
    has name: str = "";
    has allowed_labels: list[str] = [];
}

# ---------- the catalog (chokepoint) ----------

node Catalog {
    has name: str = "";
    has labels: list[str] = [];
}

# ---------- the snapshot: scoped view, built in ONE place ----------

node ReadSnapshot {
    has principal_name: str = "";
    has visible_labels: list[str] = [];
    has blocked_count: int = 0;
    has blocked_exists: int = 0;
    has leaked_error: int = 0;

    # The single materialization path. Every row must pass through here.
    # Returns None if the row's label is not in the principal's view OR
    # if the row is tombstoned. Callers cannot bypass this.
    def materialize(row_label: str, row_tombstoned: bool) -> str | None {
        if row_tombstoned {
            return None;
        }
        if row_label not in self.visible_labels {
            return None;
        }
        return row_label;
    }

    # count() / count(*): the fast path. A scoped snapshot reports
    # its own counter, not a global one — so the principal cannot
    # learn the size of a label it cannot see.
    def count(label: str) -> int {
        if label not in self.visible_labels {
            self.blocked_count = self.blocked_count + 1;
            return 0;
        }
        return 1;
    }

    # labels(n): enumerates what a principal can see. The unlabeled
    # MATCH (n) full scan uses this as its universe.
    def list_visible() -> list[str] {
        return self.visible_labels;
    }

    # Error text uniformity: an unauthorized caller cannot tell
    # "absent" from "forbidden". Both surface the same word.
    def reason() -> str {
        return "not found";
    }
}

# ---------- walker: build the snapshot ONCE, then traverse ----------

walker ScopeAndTraverse {
    has principal_name: str = "";
    has allowed: list[str] = [];
    has snap: ReadSnapshot | None = None;
    has summary: dict = {};

    can start with Root entry {
        visit [-->];
    }

    can scope with Principal entry {
        self.allowed = here.allowed_labels;
        self.principal_name = here.name;
        visit [->:Executes:->];
    }

    can build_snapshot with Catalog entry {
        # THIS is the chokepoint — one place, applied to all 86 sites
        # for free. The snapshot sees only labels the principal owns.
        filtered: list[str] = [];
        for lbl in here.labels {
            if lbl in self.allowed {
                filtered.append(lbl);
            }
        }
        self.snap = ReadSnapshot(
            principal_name=self.principal_name,
            visible_labels=filtered
        );
        self.summary["snap"] = self.snap;
        visit [->:MemberOf:->];
    }

    can materialize_rows with Row entry {
        snap_ref = self.summary["snap"];
        outcome = snap_ref.materialize(here.label_name, here.tombstoned);
        if outcome is None {
            snap_ref.blocked_exists = snap_ref.blocked_exists + 1;
            tag = "tombstoned" if here.tombstoned else "denied label";
            print(f"  [hidden] {here.label_name} ({tag})");
        } else {
            print(f"  visible row: {here.label_name}");
        }
        visit [->:MemberOf:->];
    }
}

# ---------- the demo ----------

with entry {
    # A small catalog with three labels.
    catalog_node = Catalog(
        name="main",
        labels=["User", "Post", "Secret"]
    );

    # A principal allowed to see only User and Post — NOT Secret.
    alice = Principal(
        name="alice",
        allowed_labels=["User", "Post"]
    );

    # A few rows, including a tombstoned one and one in a denied label.
    root ++> alice;
    root +>:Executes(query_kind="READ"):+> catalog_node;
    catalog_node +>:MemberOf:+> Row(label_name="User", tombstoned=False);
    catalog_node +>:MemberOf:+> Row(label_name="Post", tombstoned=False);
    catalog_node +>:MemberOf:+> Row(label_name="Post", tombstoned=True);
    catalog_node +>:MemberOf:+> Row(label_name="Secret", tombstoned=False);

    # Build a scoped snapshot for alice — the ONE chokepoint.
    snap = ReadSnapshot(
        principal_name="alice",
        visible_labels=alice.allowed_labels
    );

    print(f"snapshot for {snap.principal_name}: "
          f"visible = {snap.list_visible()}");

    # The leak surface — all answered from the same scoped snapshot.
    print(f"count(User)   = {snap.count('User')}   (allowed)");
    print(f"count(Secret) = {snap.count('Secret')}   "
          f"(denied, blocked_count={snap.blocked_count})");
    print(f"reason()      = {snap.reason()!r} (uniform — absent == forbidden)");

    # A direct read of a denied label: indistinguishable from absent.
    denied = snap.materialize("Secret", row_tombstoned=False);
    print(f"materialize('Secret', live) = {denied}");

    tomb = snap.materialize("Post", row_tombstoned=True);
    print(f"materialize('Post', tomb)  = {tomb}");

    alive = snap.materialize("User", row_tombstoned=False);
    print(f"materialize('User', live)  = {alive}");

    # The walker demonstrates the chokepoint over a real graph.
    # It is spawned so traversal actually happens end-to-end.
    print("walker traversal through the single chokepoint:");
    root spawn ScopeAndTraverse(principal_name="alice");
}
```

```jac
"""Ledger validation sweep: resume a sweep and re-validate stale `completed` records.

Mirrors the issue's core concern: on resume, completed ledger records must be
re-validated (run_dir exists, manifest matches identity, scoring artifact hashes
match) before they are trusted. Records that fail validation are demoted from
`completed` to `stale` so the walker recomputes their scores instead of
silently carrying stale data.
"""

node Run {
    has name: str = "";
    has run_dir: str = "";
    has manifest_ok: bool = False;
    has artifact_hash_ok: bool = False;
    has score: int = 0;
    has status: str = "pending";
}

node Sweep {
    has label: str = "";
}

edge LedgerEntry {
    has recorded_at: str = "";
}

edge SweepRoot { }

walker ResumeSweep {
    has sweep_label: str = "";
    has demoted: list[str] = [];
    has validated: list[str] = [];
    has failures: list[str] = [];

    can start with Root entry {
        print(f"== Resuming sweep '{self.sweep_label}' ==");
        visit [-->];
    }

    can audit with Sweep entry {
        print(f"-- auditing sweep: {here.label} --");
        visit [-->];
    }

    can validate_run with Run entry {
        reason = "ok";
        if here.run_dir == "" {
            reason = "missing run_dir";
        } elif not here.manifest_ok {
            reason = "manifest mismatch";
        } elif not here.artifact_hash_ok {
            reason = "artifact hash mismatch";
        }

        if reason != "ok" and here.status == "completed" {
            here.status = "stale";
            self.demoted.append(here.name);
            print(f"   [DEMOTE] {here.name}: completed -> stale ({reason})");
            visit [-->];
            return;
        }

        if reason != "ok" {
            self.failures.append(here.name);
            print(f"   [FAIL] {here.name}: {reason} (status={here.status})");
            visit [-->];
            return;
        }

        here.status = "completed";
        self.validated.append(here.name);
        verdict = "verified" if here.artifact_hash_ok else "trust-but-verify";
        print(f"   [OK] {here.name}: {verdict}, score={here.score}");

        visit [-->];
    }
}

walker RecomputeStale {
    has sweep_label: str = "";
    has recomputed: list[str] = [];

    can start with Root entry {
        print(f"== Recomputing stale arms for sweep '{self.sweep_label}' ==");
        visit [-->];
    }

    can visit_sweep with Sweep entry {
        visit [-->];
    }

    can recompute with Run entry {
        if here.status == "stale" {
            here.status = "completed";
            here.score = here.score + 10 if here.score > 0 else 7;
            here.manifest_ok = True;
            here.artifact_hash_ok = True;
            self.recomputed.append(here.name);
            print(f"   [RECOMP] {here.name}: recomputed score={here.score}");
        }
        visit [-->];
    }
}

with entry {
    sweep = Sweep(label="bayes-opt-2024");
    root +>:SweepRoot:+> sweep;

    arm_a = Run(name="arm-A", run_dir="/sweeps/bayes-opt/0", manifest_ok=True, artifact_hash_ok=True, score=42, status="completed");
    arm_b = Run(name="arm-B", run_dir="", manifest_ok=False, artifact_hash_ok=False, score=17, status="completed");
    arm_c = Run(name="arm-C", run_dir="/sweeps/bayes-opt/2", manifest_ok=True, artifact_hash_ok=False, score=23, status="completed");
    arm_d = Run(name="arm-D", run_dir="/sweeps/bayes-opt/3", manifest_ok=True, artifact_hash_ok=True, score=31, status="pending");

    sweep +>:LedgerEntry(recorded_at="t0"):+> arm_a;
    sweep +>:LedgerEntry(recorded_at="t1"):+> arm_b;
    sweep +>:LedgerEntry(recorded_at="t2"):+> arm_c;
    sweep +>:LedgerEntry(recorded_at="t3"):+> arm_d;

    auditor = ResumeSweep(sweep_label=sweep.label);
    root spawn auditor;

    print("");
    print(f"validated: {auditor.validated}");
    print(f"demoted to retry: {auditor.demoted}");
    print(f"other failures: {auditor.failures}");

    print("");
    recomputer = RecomputeStale(sweep_label=sweep.label);
    root spawn recomputer;

    print("");
    print(f"recomputed stale arms: {recomputer.recomputed}");
}
