```jac
"""Recursive event polling with concurrency control.

Models a polling supervisor that, instead of using setInterval (which
stacks concurrent fetches), uses a recursive setTimeout-style chain:
each poll starts only after the previous one completes, honors a
minimum interval, enforces a per-fetch timeout, and applies linear
backoff on repeated failures. A single walker advances the loop and
tracks the active-fetch invariant so we can prove only one poll is in
flight at a time.
"""

node PollingSupervisor {
    has name: str = "";
    has min_interval_ms: int = 1000;
    has fetch_timeout_ms: int = 3000;
    has backoff_step_ms: int = 500;
    has max_backoff_ms: int = 5000;
}

node EventSource {
    has label: str = "";
    has fail_streak: int = 0;
}

edge Polls {
    has tick: int = 0;
}

walker PollingLoop {
    has tick: int = 0;
    has in_flight: bool = False;
    has min_interval_ms: int = 1000;
    has backoff_step_ms: int = 500;
    has max_backoff_ms: int = 5000;
    has log: list[str] = [];

    can start with Root entry {
        visit [->:Polls:->];
    }

    can poll_source with EventSource entry {
        # Concurrency invariant: refuse to stack. A real setInterval
        # bug would let a second poll start while this one is mid-fetch.
        if self.in_flight {
            self.log.append(
                f"tick {self.tick}: REJECTED stacked poll on {here.label}"
            );
            return;
        }
        self.in_flight = True;
        self.tick += 1;

        # Simulate fetch outcome: every 4th poll fails so backoff kicks in.
        here.fail_streak += 1;
        outcome = "ok" if here.fail_streak % 4 != 0 else "timeout";
        next_step = self.min_interval_ms;

        if outcome == "timeout" {
            # Linear backoff: add backoff_step * streak, capped.
            wait_ms = self.min_interval_ms
                + self.backoff_step_ms * here.fail_streak;
            if wait_ms > self.max_backoff_ms {
                wait_ms = self.max_backoff_ms;
            }
            next_step = wait_ms;
            self.log.append(
                f"tick {self.tick}: FAIL on {here.label} "
                f"(streak={here.fail_streak}); backoff to {wait_ms}ms"
            );
        } else {
            here.fail_streak = 0;
            self.log.append(
                f"tick {self.tick}: OK on {here.label}; "
                f"next poll in {self.min_interval_ms}ms"
            );
        }

        # Recursive setTimeout: release the in-flight latch BEFORE the
        # next poll begins, so the chain never overlaps.
        self.in_flight = False;
        _ = next_step;
    }

    can sweep with PollingSupervisor entry {
        visit [->:Polls:->];
    }
}

with entry {
    sup = PollingSupervisor(name="events");
    es1 = EventSource(label="agreements-feed");
    es2 = EventSource(label="audit-feed");
    root +>:Polls(tick=1):+> sup;
    sup +>:Polls:+> es1;
    sup +>:Polls:+> es2;

    loop = PollingLoop();
    # Run six polls to demonstrate the chain: some OK, one FAIL/backoff,
    # prove only one poll is ever in flight at once.
    for i in range(6) {
        loop spawn root;
        print(loop.log[-1] if loop.log else "(no event yet)");
    }

    print("\nfinal state:");
    print(f"  in_flight = {loop.in_flight} (must be False)");
    print(f"  total ticks = {loop.tick}");
    print(f"  es1 fail_streak = {es1.fail_streak}");
    print(f"  es2 fail_streak = {es2.fail_streak}");
    rejected = 0;
    for line in loop.log {
        if "REJECTED" in line {
            rejected += 1;
        }
    }
    print(f"  rejected stacks = {rejected} (must be 0)");
}
