```jac
"""Hermes Mac-control execution context propagation.

Models the essential scenario from electricsheephq/evaos-desktop-bridge #320:
a verified broker-signed execution context must survive traversal from the
authenticated gateway ingress, across WebSocket handling, async dispatcher,
raw threading.Thread seams, and into a Mac-control tool call — without ever
being replaced by caller-supplied context.

Walker ContextPropagator enters the gateway, walks through every stage of
the request pipeline (ingress -> session -> dispatcher -> raw thread seam
-> tool executor), verifies the context at each typed boundary, and refuses
to forward anything that does not match the trusted, broker-issued payload.
A second walker ContextAuditor replays the same traversal asking only
whether the ambient context remained identical at every step.
"""

node GatewayIngress {
    has ingress_id: str = "";
    has pinned_verify_key: str = "broker-pinned-pubkey";
    has verified_context: str = "";
    has verified_tool_call_id: str = "";
    has trusted: bool = True;
}

node Session {
    has session_id: str = "";
    has ambient_context: str = "";
    has tool_call_id: str = "";
}

node Dispatcher {
    has dispatcher_name: str = "";
    has copy_context_applied: bool = True;
}

node RawThreadSeam {
    has thread_name: str = "";
    has inherited_context: bool = False;
    has bind_reset_applied: bool = False;
    has ambient_context: str = "";
}

node MacControlTool {
    has tool_name: str = "";
    has received_context: str = "";
    has received_tool_call_id: str = "";
    has is_mac_control: bool = True;
}

edge Authenticated {
    has verified_at: str = "";
}

edge SessionBound {
    has bound_at: str = "";
}

edge Dispatched {
    has dispatch_id: str = "";
}

edge RawThreadFork {
    has fork_reason: str = "";
}

edge ToolCall {
    has call_seq: int = 0;
}

walker ContextPropagator {
    has expected_context: str = "broker-ctx-MAC-CTRL-v1";
    has expected_tool_call_id: str = "tcid-7f3a";
    has failures: int = 0;

    can start with Root entry {
        print(f"[propagator] entering gateway with expected context={self.expected_context}");
        visit [-->];
    }

    can verify_ingress with GatewayIngress entry {
        ok = here.trusted
            and here.verified_context == self.expected_context
            and here.verified_tool_call_id == self.expected_tool_call_id;
        if not ok {
            self.failures += 1;
            print(f"[propagator] REJECT at ingress {here.ingress_id}: tampered/wrong payload");
            disengage;
        }
        print(f"[propagator] ingress {here.ingress_id} verified context OK");
        visit [->:Authenticated:->];
    }

    can propagate_session with Session entry {
        if here.ambient_context != self.expected_context
            or here.tool_call_id != self.expected_tool_call_id {
            self.failures += 1;
            print(f"[propagator] REJECT at session {here.session_id}: context mutated");
            disengage;
        }
        print(f"[propagator] session {here.session_id} carries verified context");
        visit [->:SessionBound:->];
    }

    can propagate_dispatcher with Dispatcher entry {
        if not here.copy_context_applied {
            self.failures += 1;
            print(f"[propagator] REJECT at dispatcher {here.dispatcher_name}: copy_context missing");
            disengage;
        }
        print(f"[propagator] dispatcher {here.dispatcher_name} applied copy_context");
        visit [->:Dispatched:->];
    }

    can bind_raw_thread with RawThreadSeam entry {
        if not here.bind_reset_applied {
            self.failures += 1;
            print(f"[propagator] REJECT at raw thread {here.thread_name}: explicit bind/reset missing");
            disengage;
        }
        if not here.inherited_context {
            self.failures += 1;
            print(f"[propagator] REJECT at raw thread {here.thread_name}: context lost across seam");
            disengage;
        }
        if here.ambient_context != self.expected_context {
            self.failures += 1;
            print(f"[propagator] REJECT at raw thread {here.thread_name}: wrong ambient context");
            disengage;
        }
        print(f"[propagator] raw thread {here.thread_name} bound + reset verified context");
        visit [->:RawThreadFork:->];
    }

    can forward_to_tool with MacControlTool entry {
        if not here.is_mac_control {
            self.failures += 1;
            print(f"[propagator] REJECT tool {here.tool_name}: not Mac-control");
            disengage;
        }
        if here.received_context != self.expected_context
            or here.received_tool_call_id != self.expected_tool_call_id {
            self.failures += 1;
            print(f"[propagator] REJECT tool {here.tool_name}: payload mismatch");
            disengage;
        }
        print(f"[propagator] forwarded verified context into tool {here.tool_name}");
    }
}

walker ContextAuditor {
    has expected_context: str = "broker-ctx-MAC-CTRL-v1";
    has expected_tool_call_id: str = "tcid-7f3a";
    has mismatched: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit_session with Session entry {
        if here.ambient_context != self.expected_context {
            self.mismatched += 1;
        }
        visit [->:SessionBound:->];
    }

    can audit_dispatcher with Dispatcher entry {
        if not here.copy_context_applied {
            self.mismatched += 1;
        }
        visit [->:Dispatched:->];
    }

    can audit_raw with RawThreadSeam entry {
        if here.ambient_context != self.expected_context
            or not here.inherited_context {
            self.mismatched += 1;
        }
        visit [->:RawThreadFork:->];
    }

    can audit_tool with MacControlTool entry {
        if here.received_context != self.expected_context
            or here.received_tool_call_id != self.expected_tool_call_id {
            self.mismatched += 1;
        }
    }
}

with entry {
    gateway = GatewayIngress(
        ingress_id="gw-01",
        verified_context="broker-ctx-MAC-CTRL-v1",
        verified_tool_call_id="tcid-7f3a",
        trusted=True
    );
    s1 = Session(
        session_id="sess-A",
        ambient_context="broker-ctx-MAC-CTRL-v1",
        tool_call_id="tcid-7f3a"
    );
    s2 = Session(
        session_id="sess-B",
        ambient_context="broker-ctx-MAC-CTRL-v1",
        tool_call_id="tcid-7f3a"
    );
    disp = Dispatcher(dispatcher_name="ws-dispatcher", copy_context_applied=True);
    raw = RawThreadSeam(
        thread_name="agent-build-thread-1",
        inherited_context=True,
        bind_reset_applied=True,
        ambient_context="broker-ctx-MAC-CTRL-v1"
    );
    tool = MacControlTool(
        tool_name="open_app",
        received_context="broker-ctx-MAC-CTRL-v1",
        received_tool_call_id="tcid-7f3a",
        is_mac_control=True
    );

    gateway +>:Authenticated(verified_at="2024-01-01T00:00:00Z"):+> s1;
    s1 +>:SessionBound(bound_at="2024-01-01T00:00:01Z"):+> disp;
    disp +>:Dispatched(dispatch_id="d-9"):+> raw;
    raw +>:RawThreadFork(fork_reason="agent-build"):+> tool;

    root ++> gateway;

    root spawn ContextPropagator();
    root spawn ContextAuditor();
}
