    override def shipping_cost() -> float {
        return 0.0;
    }
    override def handling_label() -> str {
        return "DIGITAL DELIVERY";
    }
}

node Electronics(Product) {
    has brand: str = "";
    has warranty_months: int = 0;
    override def shipping_cost() -> float {
        return 12.99 + 1.25 * self.weight;
    }
    override def handling_label() -> str {
        return "INSURED";
