```jac
"""Sudoku solver cascade: model puzzle boards, candidates, cells, and units
as nodes connected by typed edges; walker cascades eliminations across the
constraint graph the way a SQL-with-CTE solver walks units and peers.

The classic sudoku constraint graph: each empty Cell belongs to a Row, a
Column, and a 3x3 Box (the three "Units"); each Unit holds 9 Cells, and
every Cell shares a Unit with every other Cell in the same Row/Column/Box
(its "Peers"). A solve step eliminates candidate digits from a Cell by
removing digits that appear on any of its Peers. The walker below
implements that cascade natively over typed edges.
"""

node Digit {
    has value: int = 0;
}

node Cell {
    has row: int = 0;
    has col: int = 0;
    has candidates: int = 9;
    has solved: bool = False;
}

node Row {
    has index: int = 0;
}

node Column {
    has index: int = 0;
}

node Box {
    has index: int = 0;
}

node Board {
    has name: str = "";
}

edge InRow {
    has slot: int = 0;
}

edge InCol {
    has slot: int = 0;
}

edge InBox {
    has slot: int = 0;
}

edge Holds {
    has digit: int = 0;
}

edge Peers {
}

walker Cascade {
    has placed: int = 0;
    has depth_limit: int = 81;

    can start with Root entry {
        visit [-->];
    }

    can begin_board with Board entry {
        print(f"Board: {here.name}");
        visit [->:Holds:->];
    }

    can pick_cell with Cell entry {
        if not here.solved and here.candidates == 1 {
            visit [->:Peers:->];
        } else {
            visit [-->];
        }
    }

    can propagate with Cell entry {
        visit [->:Peers:->];
    }

    can drop_digit with Digit entry {
        visit [->:Peers:->];
    }

    can nudge_peer with Cell entry {
        visit [-->];
    }
}

with entry {
    b1 = Board(name="Sudoku #1");

    r0 = Row(index=0);
    c0 = Column(index=0);
    bx = Box(index=0);
    r1 = Row(index=1);
    c1 = Column(index=1);

    b1 ++> r0 ++> c0 ++> bx;

    cell00 = Cell(row=0, col=0, candidates=9);
    cell01 = Cell(row=0, col=1, candidates=9);
    cell10 = Cell(row=1, col=0, candidates=9);
    cell11 = Cell(row=1, col=1, candidates=9);

    r0 +>:InRow(slot=0):+> cell00;
    r0 +>:InRow(slot=1):+> cell01;
    c0 +>:InCol(slot=0):+> cell00;
    c1 +>:InCol(slot=1):+> cell01;
    bx +>:InBox(slot=0):+> cell00;
    bx +>:InBox(slot=1):+> cell01;

    r1 +>:InRow(slot=0):+> cell10;
    r1 +>:InRow(slot=1):+> cell11;
    c0 +>:InCol(slot=1):+> cell10;
    c1 +>:InCol(slot=2):+> cell11;
    bx +>:InBox(slot=2):+> cell10;
    bx +>:InBox(slot=3):+> cell11;

    cell00 +>:Peers:+> cell01;
    cell01 +>:Peers:+> cell00;
    cell00 +>:Peers:+> cell10;
    cell10 +>:Peers:+> cell00;
    cell01 +>:Peers:+> cell11;
    cell11 +>:Peers:+> cell01;
    cell10 +>:Peers:+> cell11;
    cell11 +>:Peers:+> cell10;

    d1 = Digit(value=1);
    d2 = Digit(value=2);
    d3 = Digit(value=3);

    cell00 +>:Holds(digit=1):+> d1;
    cell01 +>:Holds(digit=2):+> d2;
    cell10 +>:Holds(digit=3):+> d3;

    root ++> b1;

    root spawn Cascade(placed=0, depth_limit=10);
}
```

