```jac
"""Typst #8066: infinite recursion in show rules leaks memory.

Models the failing show rule
    #show math.mat: it => math.mat(it.rows)
as a recursive application walker. Each Matrix node holds a MatShow
edge back to itself (the show rule), so traversing the show relationship
indefinitely keeps re-applying the rule. The CyclicShowWalker reproduces
the runaway recursion with an explicit visited-set guard (the typical
user-side mitigation), while the UnguardedShowWalker demonstrates the
leak that the issue reports.
"""

# ---------------------------------------------------------------------------
# Entity archetypes
# ---------------------------------------------------------------------------

node Matrix {
    has name: str = "";
    has rows: int = 0;
    has rendered_bytes: int = 0;
}

# A show-rule application is *applied to* a Matrix. The relationship is
# semantic (it is the `it => math.mat(it.rows)` re-render), so we model
# it as a typed edge carrying the rule text.
edge MatShow {
    has rule: str = "";
}

# ---------------------------------------------------------------------------
# Walker: the unmitigated recursive show-rule traversal
# ---------------------------------------------------------------------------

walker UnguardedShowWalker {
    has depth: int = 0;
    has max_steps: int = 50;
    has steps: int = 0;

    can start with Root entry {
        visit [-->];
    }

    # Visiting a Matrix triggers its show rule, which is itself another
    # MatShow edge leading back into the same kind of node graph. Without
    # a guard, this mirrors the typst OOM behavior: the walker keeps
    # applying the rule, allocations (rendered_bytes) grow, and we cap
    # the demo with max_steps so it terminates.
    can apply with Matrix entry {
        self.steps += 1;
        here.rendered_bytes += 1024 * 1024;  # ~1 MiB per step, like the leak
        if self.steps >= self.max_steps {
            print(
                f"[unguarded] OOM-equivalent at step {self.steps}: "
                f"rendered_bytes={here.rendered_bytes}"
            );
            disengage;
        }
        visit [->:MatShow:->];
    }
}

# ---------------------------------------------------------------------------
# Walker: the mitigated traversal (explicit visited-set, the
# cycle-policy that the user was about to add)
# ---------------------------------------------------------------------------

walker CyclicShowWalker {
    has visited: list[str] = [];
    has steps: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can apply with Matrix entry {
        if here.name in self.visited {
            print(
                f"[guarded] cycle detected at '{here.name}' after "
                f"{self.steps} steps — disengaging like the user's "
                f"proposed base case would"
            );
            disengage;
        }
        self.visited.append(here.name);
        self.steps += 1;
        here.rendered_bytes += 256;  # bounded by cycle guard
        visit [->:MatShow:->];
    }
}

# ---------------------------------------------------------------------------
# Demo: a single Matrix node with a self-loop show rule, plus a chain
# showing the cascade the second snippet in the issue exercises.
# ---------------------------------------------------------------------------

with entry {
    # The pathological case: math.mat(it.rows) is registered as a
    # show rule ON math.mat, producing a self-referential graph.
    m = Matrix(name="mat()", rows=1);
    m +>:MatShow(rule="math.mat(it.rows)"):+> m;

    # A second matrix that legitimately chains through one intermediate
    # node, to show the walker traverses MatShow edges in order.
    m2 = Matrix(name="derived", rows=2);
    m3 = Matrix(name="expanded", rows=4);
    m2 +>:MatShow(rule="expand"):+> m3;

    root ++> m ++> m2;

    print("=== UnguardedShowWalker (mirrors the reported OOM) ===");
    root spawn UnguardedShowWalker();

    print("=== CyclicShowWalker (the user's proposed base case) ===");
    root spawn CyclicShowWalker();
}
```

