```jac
"""Order auditor demonstrating skip vs halt semantics.

Orders are nodes with an amount, a validity flag, and a fraud flag.
Invalid orders are skipped (audit continues to later orders), while
any flagged-fraud order halts the entire walk on the spot via
``disengage;``. Each visited order prints one line showing which
action fired.
"""

node Order {
    has title: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    has audited: int = 0;

    can start with Root entry {
        print("OrderAuditor starting walk");
        visit [-->] else { disengage; }
    }

    can audit with Order entry {
        # Halt the whole walk if this order is flagged for fraud.
        if here.fraud {
            print(f"[HALT] fraud flag on {here.title} (${here.amount})");
            disengage;
        }
        # Skip invalid orders but keep auditing later ones.
        if not here.valid {
            print(f"[SKIP] invalid order {here.title} (${here.amount})");
            visit [-->] else { disengage; }
            return;
        }
        # Happy path: count and continue.
        self.audited += 1;
        print(f"[AUDIT] {here.title} (${here.amount})");
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Order(title="Order-001", amount=120.50, valid=True, fraud=False)
        ++> Order(title="Order-002", amount=45.00, valid=False, fraud=False)
        ++> Order(title="Order-003", amount=999.99, valid=True, fraud=False)
        ++> Order(title="Order-004", amount=300.00, valid=True, fraud=True)
        ++> Order(title="Order-005", amount=80.00, valid=True, fraud=False);

    auditor = OrderAuditor();
    root spawn auditor;

    print(f"Auditor finished with {auditor.audited} valid orders counted");
}
```

