```jac
"""Build system dependency graph: count total build minutes, auditing each
task exactly once even when diamond-shaped dependencies reach it many times.
"""

node Task {
    has name: str = "";
    has minutes: int = 0;
    has audited: bool = False;
}

walker BuildAuditor {
    has total_minutes: int = 0;
    has visited_names: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Task entry {
        already = False;
        for n in self.visited_names {
            if n == here.name {
                already = True;
                break;
            }
        }
        if not already and not here.audited {
            here.audited = True;
            self.total_minutes += here.minutes;
            self.visited_names.append(here.name);
            print(f"  + auditing {here.name} (+{here.minutes} min) -> running total {self.total_minutes}");
        } else {
            print(f"  = skipping {here.name} (already audited)");
        }
        visit [-->];
    }
}

with entry {
    # Diamond shape: core -> http, core -> json; app depends on both http & json
    # so `core` is reachable by two paths but must be audited once.
    core = Task(name="core-lib", minutes=30);
    http = Task(name="http-client", minutes=45);
    json = Task(name="json-parser", minutes=25);
    app = Task(name="app", minutes=60);

    root ++> core ++> http ++> app;
    root ++> core ++> json ++> app;

    print("Diamond dependency graph:");
    print("  root -> core -> http -> app");
    print("  root -> core -> json -> app");
    print("Walking the graph:\n");

    auditor = BuildAuditor();
    root spawn auditor;

    print(f"\nTotal build minutes (each task counted once): {auditor.total_minutes}");
}
```

