```jac
"""Health-inspect a restaurant kitchen line: grill, fryer, cold prep.

Two inspections run at every station:
  1. Temperature check -- flag any station above 40 C as a violation.
  2. Visit log -- record every station the inspector passes.

A plain visitor (delivery driver) does not trigger either inspection,
matching the union-trigger reference pattern.
"""

node Station {
    has station_name: str = "";
    has temperature: float = 0.0;
}

walker HealthInspector {
    has inspector_badge: str = "";
    has visited_count: int = 0;
    has violations: list[str] = [];

    can start with Root entry {
        print(f"Inspector {self.inspector_badge} beginning kitchen walk");
        visit [-->];
