    can inspect with Station entry {
        self.visited_count += 1;
        stamp = f"{self.inspector_badge}@{here.station_name}";
        if here.temperature > 40.0 {
            self.violations.append(stamp);
            print(f"[VIOLATION] {here.station_name} at {here.temperature} C");
