        print(f"Driver {self.driver_name} passing through the kitchen");
        visit [-->];
    }

    # Matches no Station ability, so the driver's pass is silent
    # -- no temperature check, no visit log on the inspector side.
    can pass_through with Station entry {
        visit [-->];
    }
}

with entry {
