```jac
"""Knowledge-graph evaluation model for WISPACE retrieval.

This is a discovery/architecture demo (no graph database implementation).
It models the core domain: knowledge entities as nodes, typed relationships
as edges, a provenance/version trail, and a walker that evaluates retrieval
scope while enforcing untrusted-knowledge isolation rules.
"""

# Provenance + freshness live on the relationship itself, so they travel
# with the edge wherever the graph is traversed.
edge Related {
    has weight: float = 0.0;
    has source: str = "";
    has version: str = "";
    has confidence: float = 0.0;
    has fresh: bool = True;
    has trustworthy: bool = True;
}

# Base node: every knowledge entry exposes a domain-kind label and a
# freshness signal that the evaluator walker can compare uniformly.
node KnowledgeItem {
    has kind: str = "";
    has title: str = "";
    has summary: str = "";
    has fresh: bool = True;
}

node Concept(KnowledgeItem) {
    has definition: str = "";
}

node Prerequisite(KnowledgeItem) {
    has skill_level: int = 0;
}

node Constraint(KnowledgeItem) {
    has rule: str = "";
}

node Source(KnowledgeItem) {
    has uri: str = "";
    has authority: float = 0.0;
}

# Tenant boundary — every knowledge item belongs to exactly one tenant.
# Server-derived learner facts NEVER appear inside the knowledge graph.
node Tenant {
    has tenant_id: str = "";
}

walker Evaluator {
    has tenant_id: str = "";
    has visited: list[str] = [];
    has depth_cap: int = 4;
    has cycle_detected: bool = False;
    has depth: int = 0;

    can begin with Root entry {
        visit [-->];
    }

    can scope with Tenant entry {
        # Bind tenant context, then walk into the tenant's knowledge subgraph.
        if here.tenant_id != self.tenant_id {
            print(f"[SKIP] tenant mismatch: walker={self.tenant_id}, node={here.tenant_id}");
            disengage;
        }
        print(f"[TENANT] scoping to {here.tenant_id}");
        visit [-->];
    }

    # Union ability: every knowledge-item subclass exposes kind/title/fresh,
    # so we can score it with a single routine instead of four duplicates.
    can score with Concept | Prerequisite | Constraint | Source entry {
        self.visited.append(here.title);

        trust = "TRUSTED" if here.fresh else "STALE";
        print(f"  [{trust}] {here.kind}: {here.title}");

        # Stop descending when the item is stale — untrusted knowledge cannot
        # be propagated further down the traversal.
        if not here.fresh {
            print("    -> halting descent (stale knowledge)");
            disengage;
        }

        # Forward traverse only along Related edges whose own freshness and
        # trust flags are still true. This is the typed-edge filter that
        # replaces the hand-rolled adjacency walk.
        next_nodes = [here ->:Related:->];
        if not next_nodes {
            disengage;
        }
        self.depth += 1;
        if self.depth > self.depth_cap {
            print("    -> depth cap reached");
            disengage;
        }
        visit next_nodes;
    }
}

with entry {
    # Two tenants — proves the walker only walks its own slice.
    acme = Tenant(tenant_id="acme");
    globex = Tenant(tenant_id="globex");

    # Build the knowledge subgraph for tenant acme.
    prereq = Prerequisite(kind="prerequisite", title="linear-algebra",
                          summary="vectors, matrices, eigenvalues",
                          skill_level=2);
    concept = Concept(kind="concept", title="gradient-descent",
                      summary="iterative optimization method",
                      definition="theta -= lr * grad");
    constraint = Constraint(kind="constraint", title="non-convexity",
                           rule="must check convexity before applying GD");
    src = Source(kind="source", title="boyd-vandenberghe",
                 uri="https://example.org/bv.pdf", authority=0.9);

    # Wire knowledge under acme.
    acme ++> prereq
        +>:Related(weight=0.8, source="curriculum-map", version="2024-Q1",
                   confidence=0.9, fresh=True, trustworthy=True):+> concept;
    prereq +>:Related(weight=0.5, source="syllabus", version="2024-Q1",
                      confidence=0.7, fresh=True, trustworthy=True):+> constraint;
    concept +>:Related(weight=0.4, source="textbook", version="2023-1",
                       confidence=0.6, fresh=False, trustworthy=False):+> src;

    # A second, completely isolated tenant slice (must NOT be reached).
    globex_concept = Concept(kind="concept", title="secret-tenant-thing",
                             summary="must never leak",
                             definition="REDACTED");
    globex ++> globex_concept;

    # Spawn the evaluator on acme's slice only.
    root ++> acme;
    root spawn Evaluator(tenant_id="acme", depth_cap=4);

    print(f"visited titles: {Evaluator().visited}");
}
