```jac
"""Restaurant kitchen health inspection.

A single inspector walker visits each kitchen station (grill, fryer,
cold prep) and runs two checks at every stop:

  1. Temperature check -- flags any station above 40 C as a violation.
  2. Visit log -- records that the inspector stopped at the station.

Both checks fire at every station regardless of which station it is,
so the inspector uses a union trigger on a small ``KitchenStation``
hierarchy.
"""

# --- Station hierarchy -----------------------------------------------------

# Base node shared by every station. The two checks operate on common
# fields (temperature + station name), so the inspector handles all
# station types with one union ability.
node KitchenStation {
    has station_name: str = "";
    has celsius: float = 0.0;
}

node Grill(KitchenStation) { }

node Fryer(KitchenStation) { }

node ColdPrep(KitchenStation) { }

# --- Inspector walker ------------------------------------------------------

walker Inspector {
    has violations: int = 0;
    has log: list[str] = [];

    can start with Root entry {
        print("Inspector beginning kitchen line walk...");
        visit [-->];
    }

    # One union ability handles every station type -- no per-station
    # duplication, and both checks fire unconditionally here.
    can inspect with Grill | Fryer | ColdPrep entry {
        # 1) Temperature violation check.
        if here.celsius > 40.0 {
            self.violations += 1;
            print(f"  [VIOLATION] {here.station_name} reads {here.celsius} C (>40 C)");
        } else {
            print(f"  [ok]        {here.station_name} reads {here.celsius} C");
        }

        # 2) Visit log entry.
        self.log.append(here.station_name);

        visit [-->];
    }
}

# --- Demo wiring -----------------------------------------------------------

with entry {
    # Build a kitchen line as a chain off of root.
    root ++> Grill(station_name="Grill", celsius=180.0)
        ++> Fryer(station_name="Fryer", celsius=175.0)
        ++> ColdPrep(station_name="Cold Prep", celsius=4.0)
        ++> Grill(station_name="Salamander", celsius=55.0)
        ++> ColdPrep(station_name="Salad Bar", celsius=6.0);

    inspector = Inspector();
    root spawn inspector;

    print("");
    print(f"Stations visited : {len(inspector.log)}");
    print(f"Visit order      : {inspector.log}");
    print(f"Violations found : {inspector.violations}");
}
```

```jac
"""Warehouse packing line: stations and robots announce each other, tally stops and boxes.

The station ability fires for any visiting robot (union trigger); the robot
ability fires for any station it stops at. Each side tallies on the walker
itself, so a single spawned walker walks the whole line.
"""

node Station {
    has name: str = "";
    has packed: int = 0;
}

node Robot {
    has label: str = "";
    has stops: int = 0;
}

walker Packer {
    has station_tally: dict = {};
    has robot_tally: dict = {};

    can start with Root entry {
        print(f"Packer starting tour of the warehouse line");
        visit [-->];
    }

    can at_station with Station entry {
        station_name = here.name;
        if station_name in self.station_tally {
            self.station_tally[station_name] = self.station_tally[station_name] + 1;
        } else {
            self.station_tally[station_name] = 1;
        }
        print(f"Station {station_name} is serving a robot (packed={here.packed})");
        visit [-->];
    }

    can at_robot with Robot entry {
        robot_name = here.label;
        if robot_name in self.robot_tally {
            self.robot_tally[robot_name] = self.robot_tally[robot_name] + 1;
        } else {
            self.robot_tally[robot_name] = 1;
        }
        here.stops += 1;
        print(f"Robot {robot_name} stopped at a station (total stops={here.stops})");
        visit [-->];
    }
}

walker RobotRunner {
    has label: str = "R-1";

    can start with Root entry {
        print(f"Robot {self.label} begins shift");
        visit [-->];
    }

    can pull_up with Station entry {
        print(f"Robot {self.label} pulls up to station {here.name}");
        here.packed += 1;
        visit [-->];
    }
}

with entry {
    s1 = Station(name="S1", packed=0);
    s2 = Station(name="S2", packed=0);
    s3 = Station(name="S3", packed=0);
    root ++> s1 ++> s2 ++> s3;

    r1 = Robot(label="R-1", stops=0);
    r2 = Robot(label="R-2", stops=0);
    root ++> r1 ++> r2;

    print("=== Stations announcing service ===");
    packer = Packer();
    root spawn packer;

    print("");
    print("=== Robots pulling up to stations ===");
    runner = RobotRunner(label="R-1");
    root spawn runner;
    runner2 = RobotRunner(label="R-2");
    root spawn runner2;

    print("");
    print("=== Tallies ===");
    print(f"Stations served (station -> times announced): {packer.station_tally}");
    print(f"Robots stopped (robot -> times announced): {packer.robot_tally}");
    print(f"Boxes packed per station: S1={s1.packed}, S2={s2.packed}, S3={s3.packed}");
    print(f"Stops per robot: R-1={r1.stops}, R-2={r2.stops}");
}
