"""Frontier sweep: L0 packaging through L1 spine with parallel L2 lanes and QA feedback."""

edge Spine { }

edge Hosts { }

edge Monitors { }

node FrontierLevel {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has ring: int = 0;
    has landed: bool = False;
    has step: int = 0;
}

node ConsumerLane {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has issue_num: int = 0;
    has landed: bool = False;
    has commit_hash: str = "";
}

node QALane {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has label: str = "Lane E";
    has reviews_done: int = 0;
    has gate_green: bool = False;
}

walker FrontierSweeper {
    has visited_keys: list[str] = [];
    has landed_levels: int = 0;
    has landed_lanes: int = 0;
    has lanes_seen: int = 0;

    can start with Root entry {
        print("=== FRONTIER SWEEP: L0 surface -> L1 spine -> L2 consumers -> L3 pattern ===");
        visit [->:Spine:->] else { disengage; };
    }

    can sweep_level with FrontierLevel entry {
        key = f"{here.title}:r{here.ring}";
        if key in self.visited_keys {
            print(f"[CYCLE-GUARD] reflexive edge blocked at {here.title}");
            disengage;
        }
        self.visited_keys.append(key);
        status = "LANDED" if here.landed else "OPEN";
        print(f"[Ring {here.ring}] {here.title} — {status}");
        if here.landed {
            self.landed_levels += 1;
        }
        if here.title == "L2 consumers" {
            visit [->:Hosts:->];
            visit [->:Spine:->] else { disengage; };
        } else {
            visit [->:Spine:->] else { disengage; };
        }
    }

    can audit_lane with ConsumerLane entry {
        self.lanes_seen += 1;
        status = "LANDED" if here.landed else "PENDING";
        if here.landed {
            self.landed_lanes += 1;
        }
        hash_suffix = f" @{here.commit_hash}" if here.landed else "";
        print(f"    L2 #{here.issue_num} [{status}] {here.title}{hash_suffix}");
    }
}

walker QAPatrol {
    has pass_count: int = 0;
    has watch_count: int = 0;

    can start with Root entry {
        print("--- Lane E: continuous QA / downstream review ---");
        visit [->:Monitors:->] else { disengage; };
    }

    can review with FrontierLevel | ConsumerLane entry {
        verdict = "PASS" if here.landed else "WATCH";
        if here.landed {
            self.pass_count += 1;
        } else {
            self.watch_count += 1;
        }
        print(f"[QA] {verdict}: {here.title}");
        visit [-->];
    }

    can close_ledger with QALane entry {
        here.reviews_done = self.pass_count + self.watch_count;
        here.gate_green = self.watch_count == 0;
        gate_label = "GREEN" if here.gate_green else "WATCH";
        print(f"[QA] {here.label}: {here.reviews_done} reviews, gate {gate_label}");
    }
}

with entry {
    l0 = FrontierLevel(
        title="L0 MCP+packaging", year=2026, available=True, ring=0, landed=True, step=0
    );
    l1 = FrontierLevel(
        title="L1 BD3 spine", year=2026, available=True, ring=0, landed=True, step=1
    );
    l2 = FrontierLevel(
        title="L2 consumers", year=2026, available=True, ring=1, landed=True, step=2
    );
    l3 = FrontierLevel(
        title="L3 swarm pattern", year=2026, available=False, ring=2, landed=False, step=3
    );

    root +>:Spine:+> l0;
    l0 +>:Spine:+> l1;
    l1 +>:Spine:+> l2;
    l2 +>:Spine:+> l3;

    lane78 = ConsumerLane(
        title="board worker-half",
        year=78,
        available=True,
        issue_num=78,
        landed=True,
        commit_hash="9ec8e97",
    );
    lane81 = ConsumerLane(
        title="orientation",
        year=81,
        available=True,
        issue_num=81,
        landed=True,
        commit_hash="0bb6938",
    );
    lane47 = ConsumerLane(
        title="readiness",
        year=47,
        available=True,
        issue_num=47,
        landed=True,
        commit_hash="5fb3425",
    );
    lane85 = ConsumerLane(
        title="browser-use",
        year=85,
        available=True,
        issue_num=85,
        landed=True,
        commit_hash="0eae749",
    );

    l2 +>:Hosts:+> lane78;
    l2 +>:Hosts:+> lane81;
    l2 +>:Hosts:+> lane47;
    l2 +>:Hosts:+> lane85;

    qa = QALane(
        title="Lane E", year=2026, available=True, label="Lane E continuous QA", gate_green=False
    );
    root +>:Monitors:+> qa;
    root +>:Monitors:+> l0;
    root +>:Monitors:+> l1;
    root +>:Monitors:+> l2;
    root +>:Monitors:+> l3;
    root +>:Monitors:+> lane78;
    root +>:Monitors:+> lane81;
    root +>:Monitors:+> lane47;
    root +>:Monitors:+> lane85;

    sweeper = FrontierSweeper();
    root spawn sweeper;
    qa_runner = QAPatrol();
    root spawn qa_runner;

    print(
        f"Campaign tally: {sweeper.landed_levels}/4 levels landed, "
        f"{sweeper.landed_lanes}/{sweeper.lanes_seen} L2 lanes landed; "
        f"QA {qa_runner.pass_count} pass / {qa_runner.watch_count} watch"
    );
}
