```jac
"""Build-system dependency graph: walk tasks via shared-library edges and
report total build minutes, auditing each task exactly once even when
multiple paths reach it (diamond DAGs)."""

node Task {
    has name: str = "";
    has minutes: int = 0;
}

edge Needs {
    has reason: str = "runtime";
}

walker BuildAuditor {
    has total_minutes: int = 0;
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    def audit_task(task: Task) {
        if task.name not in self.visited {
            self.visited.append(task.name);
            self.total_minutes += task.minutes;
            print(f"[+] {task.name} (+{task.minutes} min, total={self.total_minutes})");
        } else {
            print(f"[skip] {task.name} already audited");
        }
    }

    can audit with Task entry {
        self.audit_task(here);
        visit [-->];
    }
}

# Walkers in jac 0.36.1 have no built-in dedupe; the explicit `visited`
# list on the walker is the audit-once guarantee across diamond paths.

with entry {
    # Diamond DAG:
    #   core <-- utils <-- app <-- reports
    #   core <--   ui   <-- app
    root ++> Task(name="core",     minutes=10)
        ++> Task(name="utils",    minutes=5)
        ++> Task(name="ui",       minutes=7)
        ++> Task(name="app",      minutes=8)
        ++> Task(name="reports",  minutes=3);

    auditor = BuildAuditor();
    root spawn auditor;

    print(f"\nTotal build minutes (each task audited once): {auditor.total_minutes}");
}
```

