"""Mutual friendships in a neighborhood: houses are nodes connected by bidirectional buddy edges."""

node House {
    has name: str = "";
    has color: str = "";
}

edge Buddy {
    has since: int = 2024;
}

walker Greeter {
    has origin: str = "";
    has hops: int = 0;

    can start with House entry {
        self.hops = self.hops + 1;
        print(f"Greeter from {self.origin} arrived at {here.name} after {self.hops} hop(s)");
        if here.name != self.origin {
            print(f"  -> reached buddy {here.name} from {self.origin}!");
            disengage;
