```jac
"""Comment moderation: immutable original body, append-only moderation history,
delete/restore transitions with role hierarchy and conflict detection.

Models the essential pieces of issue #317 as a graph:
  - Comment nodes carry the immutable original body, author, and current
    deletion state (derived from the moderation history).
  - ModerationEvent nodes are append-only; each records actor, action,
    timestamp, and reason (for deletes).
  - Author nodes declare a role (User / Admin / SuperAdmin) so role
    hierarchy is part of the graph.
  - Typed edges carry meaning: Authored, RepliedTo, Moderated.
A Moderator walker walks the moderation history of a comment to derive the
current state, enforce role hierarchy, and detect stale-version conflicts.
"""

# ---------- edge archetypes ----------
edge Authored { }
edge RepliedTo { }
edge Moderated { }

# ---------- node archetypes ----------
node Author {
    has display_name: str = "";
    has role: str = "User";  # "User" | "Admin" | "SuperAdmin"
}

node Comment {
    has body: str = "";          # IMMUTABLE original body
    has created_at: str = "";
    has is_deleted: bool = False; # projected from history
}

node ModerationEvent {
    has action: str = "";        # "delete" | "restore"
    has actor: str = "";
    has actor_role: str = "";
    has reason: str = "";        # required for delete; empty for restore
    has ts: str = "";
    has expected_version: int = 0;
}

# ---------- walker ----------
walker AuditTrail {
    has comment_body: str = "";
    has current_state: str = "active";
    has version: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can scan with Comment entry {
        # Snapshot the immutable original body so a downstream caller
        # could (in an authorized admin context) return it.
        self.comment_body = here.body;
        visit [->:Moderated:->];
    }

    can record with ModerationEvent entry {
        # Walk history in graph order, last-write-wins projected state.
        self.version += 1;
        if here.action == "delete" {
            self.current_state = "deleted";
        } elif here.action == "restore" {
            self.current_state = "active";
        }
        visit [->:Moderated:->];
    }
}

walker Moderator {
    has actor_name: str = "admin1";
    has actor_role: str = "Admin";
    has action: str = "delete";        # "delete" | "restore"
    has reason: str = "";
    has expected_version: int = -1;
    has conflict: str = "";
    has applied: bool = False;
    has target_author_role: str = "User";

    # Role hierarchy: cannot moderate equal-or-higher effective role.
    def role_allowed(actor_role: str, target_role: str) -> bool {
        if actor_role == "SuperAdmin" {
            return True;
        }
        if actor_role == "Admin" and target_role == "User" {
            return True;
        }
        return False;
    }

    can start with Root entry {
        visit [-->];
    }

    can find_target with Comment entry {
        if not self.role_allowed(self.actor_role, self.target_author_role) {
            self.conflict = "forbidden";
            disengage;
        }
        # Detect stale version: compare expected_version to the count of
        # existing ModerationEvent children.
        existing = [->:Moderated:->];
        current_version = 0;
        for e in existing {
            current_version += 1;
        }
        if self.expected_version >= 0 and self.expected_version != current_version {
            self.conflict = "stale_version";
            disengage;
        }
        # Mutate AFTER the version probe (two-phase), then visit to confirm.
        if self.action == "delete" and self.reason == "" {
            self.conflict = "reason_required";
            disengage;
        }
        if self.action == "restore" {
            here.is_deleted = False;
        } else {
            here.is_deleted = True;
        }
        # Append the new immutable event.
        here +>:Moderated:+> ModerationEvent(
            action=self.action,
            actor=self.actor_name,
            actor_role=self.actor_role,
            reason=self.reason,
            ts="t-now",
            expected_version=self.expected_version
        );
        self.applied = True;
        visit [->:Moderated:->];
    }
}

# ---------- demo ----------
with entry {
    # Authors with explicit roles.
    alice = Author(display_name="alice", role="User");
    bob   = Author(display_name="bob",   role="Admin");
    carol = Author(display_name="carol", role="SuperAdmin");

    # Comments authored by alice (a regular user), with an immutable body.
    root_post = Comment(body="Original text is never overwritten.",
                        created_at="t0", is_deleted=False);
    reply     = Comment(body="Reply body, also immutable.",
                        created_at="t1", is_deleted=False);

    # Build graph: root +> alice, alice +> root_post (Authored),
    # root_post +> reply (RepliedTo).
    root ++> alice;
    alice +>:Authored:+> root_post;
    root_post +>:RepliedTo:+> reply;
    reply +>:Authored:+> Author(display_name="alice2", role="User");

    # Scenario A: an Admin deletes alice's comment with a valid reason and
    # the correct expected_version (0 events so far).
    mod = Moderator(
        actor_name="bob",
        actor_role="Admin",
        action="delete",
        reason="spam",
        expected_version=0,
        target_author_role="User"
    );
    root_post spawn mod;
    print(f"[A] applied={mod.applied} conflict={mod.conflict} "
          f"is_deleted={root_post.is_deleted}");

    # Scenario B: same Admin tries to delete again with stale version.
    mod_b = Moderator(
        actor_name="bob",
        actor_role="Admin",
        action="delete",
        reason="dup",
        expected_version=0,
        target_author_role="User"
    );
    root_post spawn mod_b;
    print(f"[B] applied={mod_b.applied} conflict={mod_b.conflict}");

    # Scenario C: Admin tries to restore with a missing reason (allowed:
    # restore does NOT require a reason). Should succeed.
    mod_c = Moderator(
        actor_name="bob",
        actor_role="Admin",
        action="restore",
        reason="",
        expected_version=1,
        target_author_role="User"
    );
    root_post spawn mod_c;
    print(f"[C] applied={mod_c.applied} conflict={mod_c.conflict} "
          f"is_deleted={root_post.is_deleted}");

    # Scenario D: Admin tries to moderate a SuperAdmin's comment — forbidden.
    super_post = Comment(body="super only", created_at="t2", is_deleted=False);
    carol +>:Authored:+> super_post;
    mod_d = Moderator(
        actor_name="bob",
        actor_role="Admin",
        action="delete",
        reason="x",
        expected_version=0,
        target_author_role="SuperAdmin"
    );
    super_post spawn mod_d;
    print(f"[D] applied={mod_d.applied} conflict={mod_d.conflict}");

    # Scenario E: walk the moderation history of root_post to derive state.
    audit = AuditTrail();
    root_post spawn audit;
    print(f"[E] derived_state={audit.current_state} "
          f"original_body={audit.comment_body!r} version={audit.version}");
}
```

