```jac
"""Episode cycle detection in workflow.triggered_by chains.

Models a workflow review-request chain where one episode can trigger
another via a `triggered_by` causal reference. A walker performs a DFS
along the typed `TriggeredBy` edges and reports any cycle it finds.
"""

node Episode {
    has id: str = "";
    has status: str = "active";
}

edge TriggeredBy {
    has timestamp: str = "";
}

walker CycleHunter {
    has seen: list[str] = [];
    has path: list[str] = [];
    has cycle_found: bool = False;
    has cycle_path: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can hunt with Episode entry {
        if self.cycle_found {
            disengage;
        }
        current_id = here.id;
        self.path = self.path + [current_id];
        if current_id in self.seen {
            cycle_start = self.seen.index(current_id);
            self.cycle_path = self.path[cycle_start:] + [current_id];
            self.cycle_found = True;
            print(f"[REJECT] cycle detected: {' -> '.join(self.cycle_path)}");
            disengage;
        }
        self.seen = self.seen + [current_id];
        visit [->:TriggeredBy:->];
    }
}

with entry {
    a = Episode(id="A");
    b = Episode(id="B");
    c = Episode(id="C");
    d = Episode(id="D");

    root ++> a;
    a +>:TriggeredBy(timestamp="t1"):+> b;
    b +>:TriggeredBy(timestamp="t2"):+> c;
    c +>:TriggeredBy(timestamp="t3"):+> d;
    d +>:TriggeredBy(timestamp="t4"):+> b;

    hunter = CycleHunter();
    a spawn hunter;

    if hunter.cycle_found {
        print(f"validator would reject with cycle path: {hunter.cycle_path}");
    } else {
        print("no cycle found");
    }

    print("--- linear chain (no cycle) ---");
    hunter2 = CycleHunter();
    root ++> Episode(id="E");
    e_node = [here for here in [root -->] if here.id == "E"][0] if False else Episode(id="E");
    e_node2 = Episode(id="E");
    f = Episode(id="F");
    g = Episode(id="G");
    root ++> e_node2;
    e_node2 +>:TriggeredBy:+> f;
    f +>:TriggeredBy:+> g;
    hunter2_actual = CycleHunter();
    e_node2 spawn hunter2_actual;
    if hunter2_actual.cycle_found {
        print(f"reject: {hunter2_actual.cycle_path}");
    } else {
        print("linear chain accepted: E -> F -> G");
    }
}
```

```jac
"""Road snapping consistency demo.

Models the core entities from the RoadWeaver issue: roads hold an ordered
list of placements, plus derived bridge/tunnel spans whose endpoints index
into that list. A ``RoadSnapper`` walker simulates ``RoadSnapService``'s
shared-endpoint truncation: it replaces the first placement with a virtual
anchor copied from a neighbour road, leaves the rest untouched, and then
walks the graph to flag metadata that no longer matches the final geometry.

The graph is intentionally built so the gap between the new anchor and the
next real placement reproduces the ~38-block disconnect from the bug
report. A second walker (``ConsistencyAuditor``) traverses the road and
emits a single report describing the inconsistencies the snap introduced.
"""

node Road {
    has road_id: int = 0;
    has placements: list[tuple[int, int, int]] = [];
    has bridges: list[tuple[int, int]] = [];
    has tunnels: list[tuple[int, int]] = [];
}

node VirtualAnchor {
    has x: int = 0;
    has y: int = 0;
    has z: int = 0;
    has donor_road_id: int = 0;
}

edge Anchors {
    has role: str = "";
}

edge TruncatedFrom {
    has original_index: int = 0;
}

edge HostsSpan {
    has span_kind: str = "";
}

walker RoadSnapper {
    has donor_anchor: tuple[int, int, int] = (0, 0, 0);
    has donor_id: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can snap with Road entry {
        if here.road_id != 1 {
            visit [-->];
            return;
        }
        anchor = VirtualAnchor(
            x=self.donor_anchor[0],
            y=self.donor_anchor[1],
            z=self.donor_anchor[2],
            donor_road_id=self.donor_id,
        );
        here +>:TruncatedFrom(original_index=0):+> anchor;
        visit [-->];
    }
}

walker ConsistencyAuditor {
    has issues: list[str] = [];
    has audited_road: Road | None = None;

    can start with Root entry {
        visit [-->];
    }

    can audit_road with Road entry {
        self.audited_road = here;
        visit [-->];
    }

    can audit_anchor with VirtualAnchor entry {
        road = self.audited_road;
        if road is None {
            visit [-->];
            return;
        }
        if len(road.placements) == 0 {
            visit [-->];
            return;
        }
        anchor_pos = (here.x, here.y, here.z);
        first_real = road.placements[0];
        dx = first_real[0] - anchor_pos[0];
        dy = first_real[1] - anchor_pos[1];
        dz = first_real[2] - anchor_pos[2];
        gap = ((dx * dx + dy * dy + dz * dz) ** 0.5);
        gap_str = f"{gap:.1f}";
        if gap > 0.0 {
            msg = (
                f"DISCONNECT: virtual anchor {anchor_pos} (donor road "
                f"{here.donor_road_id}) sits {gap_str} blocks from next "
                f"real placement {first_real} on road {road.road_id}"
            );
            self.issues.append(msg);
        }
        visit [-->];
    }

    can audit_spans with Road entry {
        n = len(here.placements);
        for (lo, hi) in here.bridges {
            if lo < 0 or lo >= n or hi < 0 or hi >= n {
                msg = (
                    f"STALE_BRIDGE: road {here.road_id} bridge span "
                    f"[{lo},{hi}] out of range for {n} placements"
                );
                self.issues.append(msg);
            } else {
                msg = (
                    f"STALE_BRIDGE: road {here.road_id} bridge span "
                    f"[{lo},{hi}] not recomputed against final geometry "
                    f"({here.placements[lo]} -> {here.placements[hi]})"
                );
                self.issues.append(msg);
            }
        }
        for (lo, hi) in here.tunnels {
            if lo < 0 or lo >= n or hi < 0 or hi >= n {
                msg = (
                    f"STALE_TUNNEL: road {here.road_id} tunnel span "
                    f"[{lo},{hi}] out of range for {n} placements"
                );
                self.issues.append(msg);
            } else {
                msg = (
                    f"STALE_TUNNEL: road {here.road_id} tunnel span "
                    f"[{lo},{hi}] not recomputed against final geometry "
                    f"({here.placements[lo]} -> {here.placements[hi]})"
                );
                self.issues.append(msg);
            }
        }
        report self.issues;
    }
}

with entry {
    donor = Road(
        road_id=0,
        placements=[(666, 69, -669), (700, 70, -670), (740, 71, -671)],
        bridges=[],
        tunnels=[],
    );
    victim = Road(
        road_id=1,
        placements=[(699, 63, -689), (740, 64, -700), (780, 65, -710)],
        bridges=[(0, 2)],
        tunnels=[(1, 2)],
    );
    root ++> donor;
    root ++> victim;
    donor +>:Anchors(role="head"):+> VirtualAnchor(
        x=666, y=69, z=-669, donor_road_id=0
    );

    snapper = RoadSnapper(donor_anchor=(666, 69, -669), donor_id=0);
    root spawn snapper;

    auditor = ConsistencyAuditor();
    root spawn auditor;
    print("Final issues raised by ConsistencyAuditor:");
    for issue in auditor.issues {
        print(f"  - {issue}");
    }
    print(
        f"Total: {len(auditor.issues)} consistency problem(s) detected "
        f"after snap."
    );
}
