```jac
"""Stable-indexed ordered collection: instructions live in basic blocks and keep their identity across inserts/removes.

Models the core pain from the Swift issue: stable indices for elements (instructions)
inside a sequence (basic block) so that other structures (def-use chains) that reference
them by index are not invalidated when neighbors are inserted or removed.
"""

node Instruction {
    has opcode: str = "";
    has stable_index: int = 0;
    has alive: bool = True;
}

node BasicBlock {
    has block_name: str = "";
}

node UseSite {
    has note: str = "";
    has bound_index: int = -1;
}

edge OwnsBlock {
    has role: str = "function";
}

edge HasInstruction {
    has ordinal: int = 0;
}

edge References {
    has kind: str = "def-use";
    has ordinal: int = -1;
}

walker Inserter {
    has new_op: str = "phi";
    has block: BasicBlock | None = None;

    can start with Root entry {
        if self.block is not None {
            visit [self.block];
        } else {
            disengage;
        }
    }

    can insert with BasicBlock entry {
        new_idx = 0;
        for _ch in [-->] {
            new_idx += 1;
        }
        new_idx = new_idx + 1;
        ins = Instruction(opcode=self.new_op, stable_index=new_idx);
        here +>:HasInstruction(ordinal=new_idx):+> ins;
        print(f"inserted {ins.opcode} at stable_index={ins.stable_index} in block {here.block_name}");
    }
}

walker Invalidator {
    has target_index: int = -1;

    can start with Root entry {
        visit [-->];
    }

    can sweep_block with BasicBlock entry {
        visit [-->];
    }

    can sweep_insn with Instruction entry {
        if here.stable_index == self.target_index and here.alive {
            here.alive = False;
            print(f"invalidated instruction @ index {here.stable_index} ({here.opcode})");
        }
        visit [-->];
    }
}

walker UseAudit {
    can start with Root entry {
        visit [-->];
    }

    can audit_use with UseSite entry {
        matched = False;
        for ref in [-->] {
            if ref.alive and ref.stable_index == here.bound_index {
                matched = True;
                break;
            }
        }
        verdict = "OK" if matched else "BROKEN";
        print(f"[{verdict}] use-site '{here.note}' bound_index={here.bound_index}");
        visit [-->];
    }

    can audit_block with BasicBlock entry {
        visit [-->];
    }

    can audit_insn with Instruction entry {
        visit [-->];
    }
}

with entry {
    entry_block = BasicBlock(block_name="bb0");
    root +>:OwnsBlock(role="entry"):+> entry_block;

    i1 = Instruction(opcode="load", stable_index=1);
    i2 = Instruction(opcode="add",  stable_index=2);
    i3 = Instruction(opcode="store", stable_index=3);
    entry_block +>:HasInstruction(ordinal=1):+> i1;
    entry_block +>:HasInstruction(ordinal=2):+> i2;
    entry_block +>:HasInstruction(ordinal=3):+> i3;

    root ++> UseSite(note="uses load", bound_index=1)
        +>:References(kind="def-use", ordinal=1):+> i1;
    root ++> UseSite(note="uses add", bound_index=2)
        +>:References(kind="def-use", ordinal=2):+> i2;
    root ++> UseSite(note="uses store", bound_index=3)
        +>:References(kind="def-use", ordinal=3):+> i3;

    print("--- before insert ---");
    root spawn UseAudit();

    Inserter(new_op="ret", block=entry_block) spawn root;

    print("--- after insert (indices must still resolve) ---");
    root spawn UseAudit();

    Invalidator(target_index=2) spawn root;
}
