```jac
"""Order auditor: skip invalid orders but halt on any fraud-flagged one.

Orders are nodes carrying an amount, a validity flag, and a fraud flag.
The walker walks the order chain via plain ``-->`` edges. On every
order it prints exactly one line describing which action fired:

- ``SKIP``  -- the order is marked invalid; traversal continues.
- ``HALT``  -- the order is flagged for fraud; the walker disengages.
- ``OK``    -- the order is clean; traversal continues.

The "skip but keep going" behavior uses ``continue`` semantics: the
ability falls through and still issues ``visit [-->]``. The "halt now"
behavior uses ``disengage`` which terminates the entire walk.
"""

node Order {
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud_flag: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print("OrderAuditor: beginning audit");
        visit [-->] else {
            disengage;
        }
    }

    can audit with Order entry {
        action = "";
        if here.fraud_flag {
            action = "HALT";
            print(f"[{action}] amount={here.amount} fraud detected -- aborting walk");
            disengage;
        } elif not here.valid {
            action = "SKIP";
            print(f"[{action}] amount={here.amount} invalid -- continuing");
            visit [-->] else {
                disengage;
            }
        } else {
            action = "OK";
            print(f"[{action}] amount={here.amount} clean -- continuing");
            visit [-->] else {
                disengage;
            }
        }
    }
}

with entry {
    root ++> Order(amount=120.50, valid=True, fraud_flag=False)
        ++> Order(amount=9.99, valid=False, fraud_flag=False)
        ++> Order(amount=450.00, valid=True, fraud_flag=True)
        ++> Order(amount=75.00, valid=True, fraud_flag=False);

    root spawn OrderAuditor();
    print("OrderAuditor: done");
}
