```jac
"""Label-aware augmentation lineage: versioned policies, stable per-sample seeds, and dataset-to-model artifacts."""

edge HoldsSample {
    has slot: int = 0;
}

edge GovernedBy {
    has pipeline_seed: int = 0;
}

edge LineageFrom {
}

edge TrainsOn {
}

node SourceDataset {
    has name: str = "";
    has export_format: str = "yolo";
    has sample_count: int = 0;
}

node AugPolicy {
    has policy_name: str = "";
    has horizontal_flip_p: float = 0.5;
    has brightness_p: float = 0.2;
    has artifact_json: str = "";

    def serialize() -> str {
        return f'{{"hflip_p":{self.horizontal_flip_p},"bc_p":{self.brightness_p}}}';
    }
}

node TrainingSample {
    has sample_id: str = "";
    has sample_idx: int = 0;
    has class_labels: list[str] = [];
    has bbox_count: int = 0;
    has transform_seed: int = 0;
    has augmented: bool = False;
}

node AugmentedDataset {
    has name: str = "";
    has pipeline_seed: int = 0;
    has samples_ready: int = 0;
}

node TrainedModel {
    has model_name: str = "";
    has version: str = "";
}

walker LineageRunner {
    has pipeline_seed: int = 5191;
    has policy_artifact: str = "";
    has augmented_count: int = 0;
    has seen_ids: list[str] = [];

    can start with Root entry {
        print("=== augmentation lineage: source -> policy+seed -> dataset -> model ===");
        visit [-->];
    }

    can ingest_source with SourceDataset entry {
        print(f"Source dataset: {here.name} ({here.export_format}, {here.sample_count} samples)");
        visit [->:HoldsSample:->];
        visit [-->];
    }

    can materialize_policy with AugPolicy entry {
        here.artifact_json = here.serialize();
        self.policy_artifact = here.artifact_json;
        print(f"Policy artifact '{here.policy_name}': {here.artifact_json}");
        visit [-->];
    }

    can prepare_output with AugmentedDataset entry {
        self.pipeline_seed = here.pipeline_seed;
        print(f"Augmented dataset '{here.name}' using pipeline_seed={here.pipeline_seed}");
        visit [-->];
    }

    can augment_sample with TrainingSample entry {
        for sid in self.seen_ids {
            if sid == here.sample_id {
                print(f"CYCLE GUARD: sample {here.sample_id} already augmented — stopping");
                disengage;
            }
        }
        self.seen_ids.append(here.sample_id);
        stable_seed = self.pipeline_seed * 1000 + here.sample_idx;
        flip = (stable_seed % 2) == 0;
        here.transform_seed = stable_seed;
        here.augmented = True;
        self.augmented_count += 1;
        aug_tag = "HFLIP+labels" if flip else "labels-only";
        label_text = ",".join(here.class_labels);
        print(f"  [{here.sample_id}] seed={stable_seed} labels=[{label_text}] "
              f"bboxes={here.bbox_count} -> {aug_tag}");
    }

    can finalize_model with TrainedModel entry {
        print(f"Model artifact: {here.model_name} ({here.version})");
        print(f"Lineage complete: export -> policy({self.policy_artifact}) "
              f"+ seed({self.pipeline_seed}) -> {self.augmented_count} transformed samples -> model");
        disengage;
    }
}

with entry {
    source = SourceDataset(name="fiftyone_coco_yolo", export_format="yolo", sample_count=3);
    policy = AugPolicy(policy_name="detect_v1", horizontal_flip_p=0.5, brightness_p=0.2);
    aug = AugmentedDataset(name="aug_train_v1", pipeline_seed=5191);
    model = TrainedModel(model_name="yolov8n", version="run-001");

    s1 = TrainingSample(sample_id="img_001", sample_idx=1, class_labels=["person"], bbox_count=2);
    s2 = TrainingSample(sample_id="img_002", sample_idx=2, class_labels=["car", "person"], bbox_count=3);
    s3 = TrainingSample(sample_id="img_003", sample_idx=3, class_labels=["dog"], bbox_count=1);

    root ++> source ++> policy ++> aug ++> model;
    source +>:HoldsSample(slot=1):+> s1;
    source +>:HoldsSample(slot=2):+> s2;
    source +>:HoldsSample(slot=3):+> s3;
    policy +>:GovernedBy(pipeline_seed=5191):+> aug;
    source +>:LineageFrom:+> aug;
    aug +>:TrainsOn:+> model;

    root spawn LineageRunner();
}
```

