```jac
"""Weather sweep: visit weather stations, report each Celsius reading, then summarize min and max."""

node WeatherStation {
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[float] = [];
    has min_celsius: float = 0.0;
    has max_celsius: float = 0.0;
    has count: int = 0;

    can start with Root entry {
        visit [-->] else {
            print("readings: []");
            print("min: none, max: none");
            disengage;
        }
    }

    can read with WeatherStation entry {
        print(f"{here.location}: {here.celsius}°C");
        self.readings.append(here.celsius);
        if self.count == 0 {
            self.min_celsius = here.celsius;
            self.max_celsius = here.celsius;
        } else {
            if here.celsius < self.min_celsius {
                self.min_celsius = here.celsius;
            }
            if here.celsius > self.max_celsius {
                self.max_celsius = here.celsius;
            }
        }
        self.count += 1;
        visit [-->] else {
