```jac
"""Reports access model: published reports are world-readable; unpublished
fall back to per-instance grants. The archetype hook returns READ when
published, None otherwise, so drafts remain closable but owners can share
them selectively via grants. The publish walker flips the flag and
removes the now-redundant grant."""

node Report {
    has title: str = "";
    has year: int = 0;
    has published: bool = False;
    has grant: str = "";

    def access_hook -> str | None {
        if self.published {
            return "READ";
        }
        return None;
    }
}

walker Publisher {
    has report_title: str = "";

    can start with Root entry {
        print(f"Publisher looking for '{self.report_title}'");
        visit [-->];
    }

    can search with Report entry {
        if here.title == self.report_title {
            print(f"Found '{here.title}' ({here.year}) — publishing now");
            here.published = True;
            here.grant = "";
            print(f"  hook returns: {here.access_hook()}");
        }
        visit [-->];
    }
}

walker Auditor {
    can start with Root entry {
        print("Auditor scanning report access levels:");
        visit [-->];
    }

    can scan with Report entry {
        level = here.access_hook();
        label = "READ" if level is not None else "CLOSED";
        grant_part = f" grant={here.grant}" if level is None else "";
        print(f"  [{label}] {here.title} ({here.year}){grant_part}");
        visit [-->];
    }
}

with entry {
    q1 = Report(title="Q1 Earnings", year=2024);
    q2 = Report(title="Q2 Earnings", year=2024, grant="owner-only");
    draft = Report(title="Acquisition Memo", year=2025, grant="board-only");

    root ++> q1 ++> q2 ++> draft;

    root spawn Auditor();
    root spawn Publisher(report_title="Acquisition Memo");
    root spawn Auditor();
}
