```jac
"""Perry compile: cycle-safe static reachability for trusted JS AOT promotion.

Models collect_modules stack overflow when a package subpath resolves back to
an ancestor — unbounded recursion without an explicit visited guard.
"""

node JsPackage {
    has name: str = "";
    has trusted: bool = False;
    has has_route_entry: bool = False;
    has aot_compiled: bool = False;
}

edge Imports {
    has specifier: str = "";
}

edge SubpathResolvesTo {
    has subpath: str = "";
}

walker StaticReachabilityCollector {
    has visited: list[str] = [];
    has reachable: list[str] = [];
    has aot_promoted: list[str] = [];
    has cycles_blocked: int = 0;

    can start with Root entry {
        print("collect_modules: static reachability walk");
        visit [-->];
    }

    can collect with JsPackage entry {
        if here.name in self.visited {
            self.cycles_blocked += 1;
            print(f"[GUARD] cycle on {here.name} — would stack-overflow without visited set");
            disengage;
        }
        self.visited.append(here.name);
        self.reachable.append(here.name);
        route_label = "route" if here.has_route_entry else "no-route";
        print(f"  reach: {here.name} trusted={here.trusted} {route_label}");

        if here.trusted and not here.has_route_entry and not here.aot_compiled {
            here.aot_compiled = True;
            self.aot_promoted.append(here.name);
            print(f"  AOT-promote: {here.name}");
        }

        visit [->:Imports:->];
        visit [->:SubpathResolvesTo:->];
    }
}

with entry {
    app = JsPackage(name="app-entry", trusted=False, has_route_entry=True);
    trusted_lib = JsPackage(name="@vendor/trusted-lib", trusted=True, has_route_entry=False);
    utils = JsPackage(name="@vendor/utils", trusted=True, has_route_entry=False);
    leaf = JsPackage(name="leaf", trusted=False, has_route_entry=False);

    root ++> app;
    app +>:Imports(specifier="./trusted-lib"):+> trusted_lib;
    trusted_lib +>:Imports(specifier="./utils"):+> utils;
    trusted_lib +>:Imports(specifier="./leaf"):+> leaf;
    utils +>:SubpathResolvesTo(subpath="trusted-lib/index"):+> trusted_lib;

    collector = root spawn StaticReachabilityCollector();

    print(f"reachable={collector.reachable}");
    print(f"aot_promoted={collector.aot_promoted}");
    print(f"cycles_blocked={collector.cycles_blocked}");
    print(f"trusted_lib.aot_compiled={trusted_lib.aot_compiled}");
    print(f"utils.aot_compiled={utils.aot_compiled}");
}
