```jac
"""Job worker cascade: model the A→B→C chain and walk it recursively.

The original raw-SQL cascade in cli/worker.py only touches direct parent_id
children, so a waiting grandchild of a cascade-failed child stays stuck forever.
This demo lifts the cascade into a walker over typed Parent edges, so
grandchildren (and great-grandchildren, etc.) are resolved by the same walk.
"""

node Job {
    has name: str = "";
    has state: str = "waiting";
    has retries: int = 0;
}

edge Parent {
    has order: int = 0;
}

walker Cascade {
    has failed_names: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 16;

    can start with Root entry {
        visit [-->];
    }

    can collapse with Job entry {
        if here.state == "waiting" {
            here.state = "failed";
            self.failed_names.append(here.name);
            print(f"  cascade -> failed {here.name} (depth {self.depth})");
        }
        if self.depth >= self.max_depth {
            visit [-->] else { disengage; }
            return;
        }
        self.depth += 1;
        visit [->:Parent:->];
        self.depth -= 1;
    }
}

walker Propagate {
    can start with Root entry {
        visit [-->];
    }

    can reap with Job entry {
        if here.state == "failed" {
            print(f"reaping failed job {here.name}");
        }
        visit [-->];
    }
}

with entry {
    a = Job(name="A", state="failed", retries=3);
    b = Job(name="B", state="failed", retries=3);
    c = Job(name="C", state="waiting");
    d = Job(name="D", state="waiting");

    root ++> a;
    a +>:Parent(order=0):+> b;
    b +>:Parent(order=1):+> c;
    b +>:Parent(order=2):+> d;

    print("Before cascade, states:");
    print(f"  A={a.state} B={b.state} C={c.state} D={d.state}");

    cascade = Cascade();
    root spawn cascade;
    print(f"Cascade failed names: {cascade.failed_names}");

    print("After cascade, states:");
    print(f"  A={a.state} B={b.state} C={c.state} D={d.state}");

    print("Running reaper to confirm grandchildren resolved:");
    root spawn Propagate();
}
```

