```jac
"""Restaurant kitchen line health inspection.

A patrol walker traverses the kitchen stations (grill, fryer, cold prep).
At each station two checks run on every visit:
  1. Temperature check -- flag stations above 40 C as a violation.
  2. Visit log -- record that the patrol reached this station.

Both checks must fire at every station, so we use union triggers so
that the same patrol visits every node archetype.
"""

node Station {
    has station_name: str = "";
    has temperature: float = 0.0;
    has violations: list[str] = [];
}

node GrillStation(Station) {
    has station_name: str = "Grill";
}

