"""Online store checkout: polymorphic receipt over paper books, digital books, electronics, and clothing.

One checkout routine reacts to each product's concrete kind via a union
ability and prints an itemized receipt (subtotal, shipping, total).
"""

# ----- Product archetypes -----
node Product {
    has name: str = "";
    has price: float = 0.0;

    def shipping_cost() -> float {
        return 0.0;
    }

    def kind_label() -> str {
        return "Product";
    }
}

node PaperBook(Product) {
    has weight_lb: float = 1.0;

    override def shipping_cost() -> float {
        return 0.99 + 0.75 * self.weight_lb;
    }

    override def kind_label() -> str {
        return "PaperBook";
    }
}

node DigitalBook(Product) {
    has drm: str = "watermark";

    override def shipping_cost() -> float {
        return 0.0;
    }

    override def kind_label() -> str {
        return "DigitalBook";
    }
}

node Electronics(Product) {
    has warranty_months: int = 12;
    has fragile: bool = True;

    override def shipping_cost() -> float {
        base = 7.50;
        if self.fragile {
            base = base + 3.25;
        }
        return base;
    }

    override def kind_label() -> str {
        return "Electronics";
    }
}

node Clothing(Product) {
    has size: str = "M";

    override def shipping_cost() -> float {
        return 4.25;
    }

    override def kind_label() -> str {
        return "Clothing";
    }
}

# ----- Cart container -----
node Cart {
    has label: str = "Cart";
    has items: list = [];
}

# ----- Checkout walker -----
walker Checkout {
    has subtotal: float = 0.0;
    has shipping: float = 0.0;
    has lines: list = [];

    can start with Root entry {
        visit [-->];
    }

    can open_cart with Cart entry {
        print(f"=== Receipt for {here.label} ===");
        visit [-->];
    }

    # Single union ability: fires for any concrete product kind.
    # Every product in the union exposes shipping_cost() and kind_label()
    # (declared on the Product base), so the body only touches those.
    can ring_up with PaperBook | DigitalBook | Electronics | Clothing entry {
        ship = here.shipping_cost();
        kind = here.kind_label();
        line_total = here.price + ship;

        self.subtotal = self.subtotal + here.price;
        self.shipping = self.shipping + ship;
        self.lines.append((kind, here.name, here.price, ship, line_total));

        print(f"  [{kind}] {here.name}: "
              + f"${here.price:.2f} + ${ship:.2f} ship = ${line_total:.2f}");
        visit [-->];
    }
}

with entry {
    cart = Cart(
        label="Order #1042",
        items=[
            PaperBook(name="The Pragmatic Programmer", price=29.95, weight_lb=1.4),
            DigitalBook(name="Refactoring (eBook)", price=24.00, drm="drm-free"),
            Electronics(name="USB-C Hub", price=49.99, warranty_months=24, fragile=True),
            Clothing(name="Logo Hoodie", price=55.00, size="L"),
            PaperBook(name="Crafting Interpreters", price=32.50, weight_lb=2.1)
        ]
    );

    root ++> cart
        ++> PaperBook(name="The Pragmatic Programmer", price=29.95, weight_lb=1.4)
        ++> DigitalBook(name="Refactoring (eBook)", price=24.00, drm="drm-free")
        ++> Electronics(name="USB-C Hub", price=49.99, warranty_months=24, fragile=True)
        ++> Clothing(name="Logo Hoodie", price=55.00, size="L")
        ++> PaperBook(name="Crafting Interpreters", price=32.50, weight_lb=2.1);

    root spawn Checkout();
}
```

